<template>
  <div class="lassox-diagram__DropdownField">
    <Button
      ref="dropdownButton"
      class="lassox-diagram__DropdownField-button"
      :label="selectedOption && selectedOption.label || ''"
      :trailingIcon="showDropdownMenu ? 'expand_less' : 'expand_more'"
      @click="() => showDropdownMenu = !showDropdownMenu"
    />

    <DropdownMenu
      :opener="showDropdownMenu ? $refs.dropdownButton.$el : null"
      :close="() => showDropdownMenu = false"
    >
      <DropdownMenuItem
        v-for="option in options"
        :key="option.id"
        :icon="option.value === value ? 'check' : ' '"
        :label="option.label"
        @click="() => $emit('change', option.value)"
      />
    </DropdownMenu>
  </div>
</template>

<script lang="ts">
import { Vue, Component, Prop, Model } from 'vue-property-decorator'
import Button from './Button.vue'
import DropdownMenu from './DropdownMenu.vue'
import DropdownMenuItem from './DropdownMenuItem.vue'

interface DropdownFieldOption {
  id: string
  label: string
  value: any
}

@Component({
  components: {
    Button,
    DropdownMenu,
    DropdownMenuItem,
  },
})

export default class DropdownField extends Vue {
  @Prop({ type: Array, required: true })
  readonly options!: DropdownFieldOption[]

  @Model('change')
  readonly value?: any

  showDropdownMenu = false

  get selectedOption () {
    return this.options.find(o => o.value === this.value)
  }
}
</script>

<style lang="scss">
.lassox-diagram__DropdownField {
  &-button {
    width: 100%;
    height: 36px;
    padding: 0;
    padding-left: 12px;
    padding-right: 9px;

    .lassox-diagram__BaseButton_label {
      flex-grow: 1;
    }

    .lassox-diagram__BaseButton_trailing-icon {
      padding-left: 9px;
      margin-right: 0;
    }
  }
}
</style>
