<template>
  <div
    v-if="object"
    class="lassox-diagram__Editor"
  >
    <header class="lassox-diagram__Editor_header">
      <div class="lassox-diagram__Editor_header-title-bar">
        <div
          class="lassox-diagram__Editor_header-title-bar-title"
          v-text="`Rediger ${label}`"
        />

        <IconButton
          icon="close"
          size="normal"
          @click="onClickCloseButton"
        />
      </div>

      <div
        v-if="description"
        class="lassox-diagram__Editor_header-description"
        v-text="description"
      />

      <div class="lassox-diagram__Editor_header-actions">
        <ButtonGroup>
          <Button
            v-if="object.isEntity"
            ref="addDropdownButton"
            label="Tilføj"
            :trailingIcon="showAddDropdownMenu ? 'expand_less' : 'expand_more'"
            :disabled="!object.type.supportedRelations.size"
            @click="() => showAddDropdownMenu = !showAddDropdownMenu"
          />

          <Button
            label="Fjern"
            :disabled="object.isEntity && object.isMainEntity"
            @click="remove"
          />

          <Button
            v-if="showDetailsButton"
            :label="showDetailsButton.label || 'Vis oplysninger'"
            @click="showDetailsButton.onClick"
          />
        </ButtonGroup>

        <AddRelationDropdownMenu
          v-if="object.isEntity && object.type.supportedRelations.size"
          :entity="object"
          :opener="showAddDropdownMenu ? $refs.addDropdownButton.$el : null"
          :close="() => showAddDropdownMenu = false"
        />
      </div>
    </header>

    <div class="lassox-diagram__Editor_body-wrapper">
      <div class="lassox-diagram__Editor_body">
        <EditorFieldGroups>
          <EditorFieldGroup
            v-for="fieldGroup in visibleFieldGroups"
            :key="fieldGroup.id"
            :title="fieldGroup.title"
          >
            <EditorField
              v-for="field in fieldGroup.fields"
              :key="field.id"
              :id="field.id"
              :type="field.type"
              :title="field.title"
              :editable="field.editable"
              :formatter="field.formatter"
              :options="field.options"
              :initialValue="field.initialValue"
              :initialValueLabel="field.initialValueLabel"
              :resetValue="field.resetValue"
              :errorMessage="field.errorMessage"
              :value="field.value"
              @change="value => field.updateValue(value)"
            />
          </EditorFieldGroup>
        </EditorFieldGroups>
      </div>
    </div>

    <footer class="lassox-diagram__Editor_footer">
      <ButtonGroup align="right">
        <Button
          label="Luk"
          @click="onClickCloseButton"
        />

        <Button
          type="primary"
          label="Gem ændringer"
          :disabled="!hasChanges"
          @click="saveChanges"
        />
      </ButtonGroup>
    </footer>

    <Dialog
      v-if="showConfirmCloseDialog"
      title="Luk uden at gemme?"
      content="Du har ikke gemt dine ændringer. Er du sikker på at du vil lukke vinduet og miste dem?"
      :dismissable="true"
      size="3x"
      :onClose="() => showConfirmCloseDialog = false"
    >
      <template v-slot:actions>
        <ButtonGroup align="right">
          <Button
            label="Fortryd"
            @click="() => showConfirmCloseDialog = false"
          />

          <Button
            label="Luk uden at gemme"
            type="primary"
            @click="() => close(true)"
          />
        </ButtonGroup>
      </template>
    </Dialog>
  </div>
</template>

<script lang="ts">
import { Vue, Component, Watch, Inject } from 'vue-property-decorator'
import IconButton from './IconButton.vue'
import ButtonGroup from './ButtonGroup.vue'
import Button from './Button.vue'
import DropdownMenu from './DropdownMenu.vue'
import DropdownMenuItem from './DropdownMenuItem.vue'
import DropdownMenuDivider from './DropdownMenuDivider.vue'
import AddRelationDropdownMenu from './AddRelationDropdownMenu.vue'
import FieldContainer from './FieldContainer.vue'
import TextField from './TextField.vue'
import RadioField from './RadioField.vue'
import ColorField from './ColorField.vue'
import EditorFieldGroups from './EditorFieldGroups.vue'
import EditorFieldGroupVue from './EditorFieldGroup.vue'
import EditorFieldVue from './EditorField.vue'
import Dialog from './Dialog.vue'
import type DiagramVm from './Diagram.vue'
import { createContextItem, default as Diagram, Entity, Relation, Field } from '../diagram'
import { setDeep } from '../util/get-deep-property'
import _set from 'lodash.set'
import cloneDeep from 'lodash.clonedeep'
import { unwatchRect, watchRect } from '../util/watch-rect'

interface EditorFieldGroup {
  id: string
  title: string
  fields: EditorField[]
}

type EditorField = (
  | EditorTextField
  | EditorNumberField
  | EditorRadioField
  | EditorColorField
)

interface EditorBaseField {
  id: string
  title: string
  dataKey?: string
  styleKey?: string
  editable?: boolean
  formatter?: (value: any) => any
  valueBeforeChanges?: any
  initialValue?: any
  initialValueLabel?: string
  resetValue?: any
  value: any
  validator?: Field['validator']
  errorMessage?: string
  show: boolean
  updateValue: (value: any) => void
  updateInitialValue: (value: any) => void
  getValueLabel?: (value: any) => string | undefined
}

interface EditorTextField extends EditorBaseField {
  type: 'text'
}

interface EditorNumberField extends EditorBaseField {
  type: 'number'
}

interface EditorRadioField extends EditorBaseField {
  type: 'radio-buttons'
  options: EditorRadioFieldOption[]
}

interface EditorRadioFieldOption {
  label: string
  value: any
}

interface EditorColorField extends EditorBaseField {
  type: 'color'
}

@Component({
  components: {
    IconButton,
    ButtonGroup,
    Button,
    DropdownMenu,
    DropdownMenuItem,
    DropdownMenuDivider,
    AddRelationDropdownMenu,
    FieldContainer,
    TextField,
    RadioField,
    ColorField,
    EditorFieldGroups,
    EditorFieldGroup: EditorFieldGroupVue,
    EditorField: EditorFieldVue,
    Dialog,
  },
})

export default class Editor extends Vue {
  @Inject()
  readonly diagramVm!: DiagramVm

  @Inject()
  readonly diagram!: Diagram

  el: HTMLElement | null = null
  rect = {
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    width: 0,
    height: 0,
  }

  object: Entity | Relation | null = null
  showAddDropdownMenu = false
  fieldGroups: EditorFieldGroup[] = []

  showConfirmCloseDialog = false

  get label () {
    if (!this.object) return ''
    return this.object.type.labels.editorLabel?.(this.object.data) ?? this.object.type.labels.singular.toLowerCase()
  }

  get description () {
    if (!this.object) return undefined
    return this.object.type.labels.editorDescription?.(this.object.data)
  }

  get showDetailsButton () {
    if (!this.object?.isEntity) return null
    const { showDetailsButton } = this.object.type
    if (!showDetailsButton) return null
    if (typeof showDetailsButton === 'function') return showDetailsButton(createContextItem(this.object))
    return showDetailsButton
  }

  get visibleFieldGroups () {
    const visibleFieldGroups: EditorFieldGroup[] = []
    for (const fieldGroup of this.fieldGroups) {
      const visibleFields = fieldGroup.fields.filter(field => field.show)
      if (visibleFields.length) visibleFieldGroups.push({
        ...fieldGroup,
        fields: visibleFields,
      })
    }
    return visibleFieldGroups
  }

  get changedFieldGroups () {
    return this.fieldGroups
      .map(fieldGroup => ({
        ...fieldGroup,
        fields: fieldGroup.fields.filter(field => field.value != field.valueBeforeChanges),
      }))
      .filter(fieldGroup => fieldGroup.fields.length)
  }

  get hasChanges () {
    return !!this.changedFieldGroups.length
  }

  created () {
    this.diagram.eventBus.on('editor.open', ({ target }) => this.object = target)
    this.diagram.eventBus.on('editor.close', () => this.close(false))
    this.diagram.eventBus.on('dataUpdated', () => this.close(true))
  }

  mounted () {
    this.$watch(
      () => !!this.object,
      show => this.el = show ? this.$el as HTMLElement : null,
      { immediate: true },
    )

    this.$watch(
      () => this.el,
      (el, oldEl) => {
        if (oldEl) unwatchRect(oldEl, this.onResize)
        if (el) watchRect(el, this.onResize)
      },
      { immediate: true },
    )
  }

  beforeDestroy () {
    if (this.el) unwatchRect(this.el, this.onResize)
  }

  onResize (rect: DOMRect) {
    this.rect.top = rect.top
    this.rect.left = rect.left
    this.rect.right = rect.right
    this.rect.bottom = rect.bottom
    this.rect.width = rect.width
    this.rect.height = rect.height
  }

  onClickCloseButton () {
    if (this.hasChanges) {
      this.showConfirmCloseDialog = true
      return
    }

    this.close(true)
  }

  remove () {
    if (!this.object) return

    if (this.object.isEntity) {
      this.diagram.activeDiagram.data.remove({
        entities: [ this.object.id ],
      })
    } else {
      this.diagram.activeDiagram.data.remove({
        relations: [ this.object.id ],
      })
    }

    this.close(true)
  }

  saveChanges () {
    if (!this.object) return

    const id = this.object.id

    const contextItem = createContextItem(this.object)
    contextItem.data = cloneDeep(contextItem.data)

    const newData: Record<string, any> = {}
    const newStyle: Record<string, any> = {}

    for (const fieldGroup of this.changedFieldGroups) {
      for (const field of fieldGroup.fields) {
        field.errorMessage = ''

        if (field.dataKey) {
          _set(contextItem.data, field.dataKey, field.value)
          _set(newData, field.dataKey, field.value)
        } else if (field.styleKey) {
          _set(newStyle, field.styleKey, field.value)
        }
      }
    }

    let error = false

    for (const fieldGroup of this.fieldGroups) {
      for (const field of fieldGroup.fields) {
        const result = field.validator?.(field.value, contextItem) ?? true
        if (result === true) continue

        error = true
        field.errorMessage = result.error
      }
    }

    if (error) return

    if (this.object.isEntity) {
      this.diagram.activeDiagram.data.edit({
        entities: [{ id, data: newData, style: newStyle }],
      })
    } else {
      this.diagram.activeDiagram.data.edit({
        relations: [{ id, data: newData, style: newStyle }],
      })
    }

    this.close(true)
  }

  close (emit: boolean) {
    this.showConfirmCloseDialog = false

    if (!this.object) return

    this.object = null
    this.fieldGroups = []
    if (emit) this.diagram.eventBus.emit({ name: 'editor.close' })
  }

  @Watch('object', { immediate: true })
  onObjectChanged (object: Editor['object']) {
    if (!object) return

    const previewData = cloneDeep(object.data)
    const previewStyle = cloneDeep(object.style)
    object.previewData = previewData
    object.previewStyle = previewStyle

    const context = cloneDeep(createContextItem(object))
    context.data = previewData

    let builtTypeStyle = cloneDeep(object.builtTypeStyle)

    const buildTypeStyle = () => {
      builtTypeStyle = object.buildTypeStyle({
        context,
        builtBaseStyle: object.buildBaseStyle({ context }),
      })

      for (const field of styleFields) {
        const initialValue: any = (builtTypeStyle as any)[field.styleKey as any]

        if (field.initialValue !== initialValue) {
          if (field.value === field.initialValue) {
            field.updateValue(initialValue)
          }

          field.updateInitialValue(initialValue)
        }
      }

      this.diagram.eventBus.emit({ name: 'editor.previewUpdated' })
    }

    const buildStyle = () => {
      object.builtPreviewStyle = object.buildStyle({
        builtTypeStyle,
        style: previewStyle,
      })

      this.diagram.eventBus.emit({ name: 'editor.previewUpdated' })
    }

    const createField = (options: Omit<EditorBaseField, 'show'>): EditorBaseField => ({
      id: options.id,
      title: options.title,
      dataKey: options.dataKey,
      styleKey: options.styleKey,
      editable: options.editable ?? true,
      formatter: options.formatter,
      initialValue: options.initialValue,
      value: options.value,
      resetValue: options.resetValue,
      validator: options.validator,
      errorMessage: '',
      show: true,
      updateValue: options.updateValue,
      updateInitialValue: options.updateInitialValue,
      getValueLabel: options.getValueLabel ?? (value => String(value ?? '')),
    })

    const createTextField = (options: Omit<EditorTextField, 'type' | 'show'>): EditorTextField => ({
      ...createField(options),
      type: 'text',
    })

    const createNumberField = (options: Omit<EditorNumberField, 'type' | 'show'>): EditorNumberField => ({
      ...createField(options),
      type: 'number',
    })

    const createRadioField = (options: Omit<EditorRadioField, 'initialValueLabel' | 'getValueLabel' | 'type' | 'selectedOption' | 'initialSelectedOption' | 'show'>): EditorRadioField => ({
      ...createField({
        ...options,
        getValueLabel: value => options.options.find(o => o.value === value)?.label,
      }),
      type: 'radio-buttons',
      options: options.options,
    })

    const createBooleanField = (options: Omit<EditorBaseField, 'type' | 'show'>): EditorRadioField => createRadioField({
      ...options,
      options: [
        {
          label: 'Ja',
          value: true,
        },
        {
          label: 'Nej',
          value: false,
        },
      ],
    })

    const createColorField = (options: Omit<EditorColorField, 'type' | 'show'>): EditorColorField => ({
      ...createField(options),
      type: 'color',
    })

    const fieldGroups: EditorFieldGroup[] = []
    const styleFields: EditorField[] = []

    for (const fieldGroup of object.fieldGroups) {
      const fields: EditorField[] = []

      for (const field of fieldGroup.fields) {
        const { showInactiveEditorFields } = this.diagram

        const baseField: EditorBaseField = {
          id: field.fullId,
          title: field.title,
          dataKey: field.dataKey,
          editable: field.editable,
          formatter: field.formatter,
          value: field.getValue(previewData),
          initialValue: field.getValue(object.initialState.data),
          validator: field.validator,
          show: true,
          updateValue: value => {
            newField.value = value
            setDeep(previewData, field.dataKey, value)
            buildTypeStyle()
          },
          updateInitialValue: value => {
            newField.initialValue = value
            if (newField.getValueLabel) newField.initialValueLabel = newField.getValueLabel(value)
          },
        }

        if (!field.editable && field.formatter && field.type === 'text') {
          baseField.value = field.formatter(baseField.value)
          baseField.initialValue = field.formatter(baseField.initialValue)
        }

        let newField: EditorField

        switch (field.type) {
          case 'text': {
            baseField.value = `${baseField.value ?? ''}`
            baseField.initialValue = `${baseField.initialValue ?? ''}`
            newField = createTextField(baseField)
            break
          }

          case 'boolean': {
            baseField.value = !!baseField.value
            baseField.initialValue = !!baseField.initialValue
            newField = createBooleanField(baseField)
            break
          }
        }

        newField = {
          ...newField,
          get show () { return field.active || !!newField.errorMessage || showInactiveEditorFields },
        }

        fields.push(newField)
      }

      if (!fields.length) continue

      fieldGroups.push({
        id: `fg-${fieldGroup.id}`,
        title: fieldGroup.title,
        fields: fields,
      })
    }

    function getStyleValues<S> (object: { builtTypeStyle: S, builtStyle: S }, prop: keyof S) {
      return {
        value: object.builtStyle[prop],
        initialValue: object.builtTypeStyle[prop],
        resetValue: object.builtTypeStyle[prop],
        updateValue: () => undefined,
        updateInitialValue: () => undefined,
      }
    }

    if (this.diagram.enableStyleEditing) {
      if (object.isEntity) {
        styleFields.push(
          createColorField({
            id: 'labelsBackgroundColor',
            title: 'Top baggrundsfarve',
            styleKey: 'labelsBackgroundColor',
            ...getStyleValues(object, 'labelsBackgroundColor'),
          }),
          createColorField({
            id: 'backgroundColor',
            title: 'Baggrundsfarve',
            styleKey: 'backgroundColor',
            ...getStyleValues(object, 'backgroundColor'),
          }),
          createColorField({
            id: 'borderColor',
            title: 'Kantfarve',
            styleKey: 'borderColor',
            ...getStyleValues(object, 'borderColor'),
          }),
          createRadioField({
            id: 'borderStyle',
            title: 'Kanttype',
            styleKey: 'borderStyle',
            options: [
              {
                label: 'Solid',
                value: 'solid',
              },
              {
                label: 'Prikket',
                value: 'dotted',
              },
              {
                label: 'Stiplet',
                value: 'dashed',
              },
            ],
            ...getStyleValues(object, 'borderStyle'),
          }),
          createNumberField({
            id: 'borderWidth',
            title: 'Kantbredde',
            styleKey: 'borderWidth',
            ...getStyleValues(object, 'borderWidth'),
          }),
        )
      } else {
        styleFields.push(
          createBooleanField({
            id: 'arrowTo',
            title: 'Vis pil til',
            styleKey: 'arrowTo',
            ...getStyleValues(object, 'arrowTo'),
          }),
          createBooleanField({
            id: 'arrowFrom',
            title: 'Vis pil fra',
            styleKey: 'arrowFrom',
            ...getStyleValues(object, 'arrowFrom'),
          }),
          createRadioField({
            id: 'lineStyle',
            title: 'Linjetype',
            styleKey: 'lineStyle',
            options: [
              {
                label: 'Solid',
                value: 'solid',
              },
              {
                label: 'Prikket',
                value: 'dotted',
              },
              {
                label: 'Stiplet',
                value: 'dashed',
              },
            ],
            ...getStyleValues(object, 'lineStyle'),
          }),
          createColorField({
            id: 'lineColor',
            title: 'Linjefarve',
            styleKey: 'lineColor',
            ...getStyleValues(object, 'lineColor'),
          }),
        )
      }

      for (const field of styleFields) {
        const key = field.styleKey
        if (!key) continue

        field.updateValue = value => {
          field.value = value
          setDeep(previewStyle, key, value)
          buildStyle()
        }

        field.updateInitialValue = value => {
          field.initialValue = value
          if (field.getValueLabel) field.initialValueLabel = field.getValueLabel(field.initialValue)
          field.resetValue = value
          field.valueBeforeChanges = value
        }
      }

      if (styleFields.length) fieldGroups.push({
        id: 'style',
        title: 'Udseende',
        fields: styleFields,
      })
    }

    for (const fieldGroup of fieldGroups) {
      for (const field of fieldGroup.fields) {
        field.valueBeforeChanges = field.value
        if (field.getValueLabel) field.initialValueLabel = field.getValueLabel(field.initialValue)
      }
    }

    this.fieldGroups = fieldGroups
  }
}
</script>

<style lang="scss">
.lassox-diagram__Editor {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 400px;
  box-sizing: border-box;
  background-color: white;
  box-shadow: 0 0 10px 0 rgba(black, 0.1);

  &_header {
    display: flex;
    flex-direction: column;
    padding: 24px;
    padding-bottom: 24px + 1px;
    box-shadow: inset 0 -1px 0 0 rgba(black, 0.12);

    &-title-bar {
      display: flex;
      align-items: center;

      &-title {
        flex-grow: 1;
        padding-right: 32px;
        color: rgba(black, 0.87);
        font-size: 17px;
        line-height: 24px;
        font-weight: 500;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
      }
    }

    &-description {
      padding-top: 24px;
      margin: -4px 0;
    }

    &-actions {
      padding-top: 24px;
    }
  }

  &_body-wrapper {
    height: 1px;
    flex-grow: 1;
    padding: 24px;
    overflow-x: hidden;
    overflow-y: auto;
  }

  &_footer {
    padding: 16px 24px;
    padding-top: 17px;
    flex-shrink: 0;
    box-shadow: inset 0 1px 0 0 rgba(black, 0.12);
  }
}
</style>
