<template>
  <div class="lassox-diagram__Collapsible">
    <slot v-bind="slotProps">
      <slot name="title-bar-outer" v-bind="slotProps">
        <BaseButton
          class="lassox-diagram__Collapsible-title-bar"
          @click="() => internal.open = !internal.open"
        >
          <slot name="title-bar" v-bind="slotProps">
            <div class="lassox-diagram__Collapsible-title">
              <slot name="title" v-bind="slotProps" />
            </div>

            <Icon
              class="lassox-diagram__Collapsible-title-bar-icon"
              :icon="internal.open ? 'expand_less' : 'expand_more'"
            />
          </slot>
        </BaseButton>
      </slot>

      <slot name="content-outer" v-bind="slotProps">
        <div
          class="lassox-diagram__Collapsible-content"
          :style="internal.open ? {} : { visibility: 'hidden', height: '0' }"
        >
          <slot name="content" v-bind="slotProps" />
        </div>
      </slot>
    </slot>
  </div>
</template>

<script lang="ts">
import { Vue, Component, Model } from 'vue-property-decorator'
import BaseButton from './BaseButton.vue'
import Icon from './Icon.vue'

@Component({
  components: {
    BaseButton,
    Icon,
  },
})

export default class Collapsible extends Vue {
  @Model('update:open', Boolean)
  readonly open?: boolean

  internal = {
    open: false,
  }

  get slotProps () {
    const vm = this

    return {
      get open () { return vm.internal.open },
      set open (open) { vm.internal.open = open },
    }
  }

  created () {
    this.$watch(
      () => this.open,
      open => {
        if (open !== undefined) this.internal.open = open
      },
      { immediate: true },
    )

    this.$watch(
      () => this.internal.open,
      open => {
        if (this.open !== open) this.$emit('update:open', open)
      },
    )
  }
}
</script>

<style lang="scss">
.lassox-diagram__Collapsible {
  display: flex;
  flex-direction: column;
  align-items: stretch;

  &-title-bar {
    display: flex;
    align-items: center;
    padding: 12px 16px;
    border-radius: 4px;

    &.lassox-diagram__BaseButton > .lassox-diagram__BaseButton_outline {
      color: rgba(black, 0.12);
    }
  }

  &-title {
    width: 100%;
    padding-right: 8px;
    margin: -2px 0;
    flex-shrink: 1;
    color: rgba(black, 0.87);
    font-size: 14px;
    line-height: 20px;
    font-weight: 500;
  }

  &-title-bar-icon {
    display: flex;
    margin: -1px;
    flex-shrink: 0;
  }

  &-content {}
}
</style>
