<template>
  <div class="lassox-diagram__DatePicker">
    <Vue2DatePicker
      ref="datePicker"
      tabindex="-1"
      prefixClass="lassox-diagram__DatePicker"
      :inline="true"
      format="DD.MM.YYYY"
      titleFormat="DD.MM.YYYY"
      :disabledDate="dateIsDisabled"
      :value="date"
      @panel-change="onPanelChange"
      @change="onChange"
    />
  </div>
</template>

<script lang="ts">
import { Vue, Component, Inject } from 'vue-property-decorator'
import Vue2DatePicker from 'vue2-datepicker'
import 'vue2-datepicker/locale/da'
import type DiagramVm from './Diagram.vue'
import type Diagram from '../diagram'

@Component({
  components: {
    Vue2DatePicker,
  },
})

export default class DatePicker extends Vue {
  @Inject()
  readonly diagramVm!: DiagramVm

  @Inject()
  readonly diagram!: Diagram

  date: Date | null = null

  get max () {
    const max = new Date()
    max.setHours(0)
    max.setMinutes(0)
    max.setSeconds(0)
    max.setMilliseconds(0)
    return max
  }

  dateIsDisabled (date: Date) {
    return date.getTime() > this.max.getTime()
  }

  onPanelChange () {
    const datePicker = this.$refs.datePicker as (Vue & { $el: HTMLElement }) | undefined
    datePicker?.$el.focus()
  }

  onChange (date: Date | null) {
    const isSameDate = (a: Date | null, b: Date | null) => {
      const getString = (date: Date) => date.toISOString().split('T')[0]
      return (
        (a && b && getString(a) === getString(b))
        || a === b
      )
    }

    this.$emit('close')

    if (isSameDate(date, this.max)) {
      date = null
    }

    if (isSameDate(date, this.date)) {
      return
    }

    const load = () => this.diagram.loadNewDiagram({ onDate: date })

    if (this.diagram.hasUnsavedChanges && !this.diagram.activeDiagram.historicalDate) {
      this.diagram.store.showConfirmDialog({
        title: 'Fortsæt uden at gemme?',
        content: 'Du har ikke-gemte ændringer. Er du sikker på at du vil fortsætte?',
        confirmButtonText: 'Fortsæt',
        onConfirm: load,
      })
    } else {
      load()
    }
  }

  created () {
    this.$watch(
      () => this.diagram.activeDiagram.historicalDate,
      date => this.date = date,
      { immediate: true },
    )
  }
}
</script>

<style lang="scss">
@use 'sass:color';

$namespace: 'lassox-diagram__DatePicker';

$default-color: rgba(0, 0, 0, 0.68);
$primary-color: #FFA07A;

$calendar-active-color: #FFA07A;
$calendar-active-background-color: #FFECE4;

$calendar-hover-background-color: #F1F1F1;

@import 'vue2-datepicker/scss/index.scss';

.#{$namespace}-datepicker {
  width: 100%;
}

.#{$namespace}-datepicker-main {
  border: none;
  font-family: inherit;
}

.#{$namespace}-calendar {
  width: 100%;
  padding: 0;
}

.#{$namespace}-calendar-header {
  height: 32px;

  & > .#{$namespace}-btn {
    display: flex;
    justify-content: center;
    align-items: center;
    width: calc(100% / 7);
    height: 100%;
    padding: 0;
    transition: color 100ms;
  }

  .#{$namespace}-btn-icon-double-left,
  .#{$namespace}-btn-icon-left,
  .#{$namespace}-btn-icon-right,
  .#{$namespace}-btn-icon-double-right {
    i {
      position: relative;
      display: block;
      width: 18px;
      height: 18px;
      font-style: normal;

      &::before,
      &::after {
        position: absolute;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        display: block;
        width: 100%;
        height: 100%;
        border: none;
        font-family: 'material icons outlined';
        font-size: 18px;
        line-height: 1;
        transform: none;
      }

      &::after {
        display: none;
      }
    }
  }

  .#{$namespace}-btn-icon-double-left i::before,
  .#{$namespace}-btn-icon-double-left i::after,
  .#{$namespace}-btn-icon-left i::before {
    content: 'chevron_left';
  }

  .#{$namespace}-btn-icon-right i::before,
  .#{$namespace}-btn-icon-double-right i::before,
  .#{$namespace}-btn-icon-double-right i::after {
    content: 'chevron_right';
  }

  .#{$namespace}-btn-icon-double-left i,
  .#{$namespace}-btn-icon-double-right i {
    &::before {
      transform: translateX(-15%);
    }

    &::after {
      display: block;
      transform: translateX(15%);
    }
  }

  .#{$namespace}-calendar-header-label {
    font: inherit;
    color: rgba(0, 0, 0, 0.87);
    font-size: 14px;
    line-height: 32px;
    font-weight: 500;

    .#{$namespace}-btn {
      font: inherit;

      &:hover {
        color: $primary-color;
      }
    }
  }
}

.#{$namespace}-calendar-content {
  .cell {
    position: relative;
    font-size: 12px;
    line-height: 24px;
    transition: color 100ms;

    &,
    &.today,
    &:hover,
    &.active,
    &.disabled {
      background-color: transparent;
    }

    &.today:hover {
      color: $today-color;
    }
  }

  .cell > div {
    position: relative;
    z-index: 0;
  }

  .cell > div::before {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    width: 32px;
    height: 24px;
    z-index: -1;
    border-radius: 9999px;
    transform: translateX(-50%) translateY(-50%);
    transition: background-color 100ms, box-shadow 100ms;
  }

  .cell.today > div::before {
    box-shadow: inset 0 0 0 1px #FFD9CA;
  }

  .cell:hover > div::before {
    background-color: $calendar-hover-background-color;
  }

  .cell.active > div::before {
    background-color: $calendar-active-background-color;
  }

  .cell.disabled > div::before {
    background-color: transparent;
  }

  .#{$namespace}-table-year .cell > div::before {
    width: 48px;
  }

  .#{$namespace}-table-month .cell > div::before {
    width: 36px;
  }
}

.#{$namespace}-table-date th {
  color: rgba(0, 0, 0, 0.87);
  font-weight: 500;
}
</style>
