<template>
  <Dialog
    class="lassox-diagram__ConfirmDialog"
    :dismissable="true"
    size="3x"
    :title="title || 'Bekræft'"
    :content="content"
    :onClose="dismiss"
  >
    <template v-slot:actions>
      <ButtonGroup align="right">
        <Button
          :label="dismissButtonText || 'Fortryd'"
          @click="dismiss"
        />

        <Button
          :label="confirmButtonText || 'Bekræft'"
          type="primary"
          @click="confirm"
        />
      </ButtonGroup>
    </template>
  </Dialog>
</template>

<script lang="ts">
import { Vue, Component, Prop } from 'vue-property-decorator'
import Dialog from './Dialog.vue'
import ButtonGroup from './ButtonGroup.vue'
import Button from './Button.vue'

@Component({
  components: {
    Dialog,
    ButtonGroup,
    Button,
  },
})

export default class ConfirmDialog extends Vue {
  @Prop(String)
  readonly title?: string

  @Prop(String)
  readonly content?: string

  @Prop(String)
  readonly confirmButtonText?: string

  @Prop(String)
  readonly dismissButtonText?: string

  @Prop(Function)
  readonly onConfirm?: () => void

  @Prop(Function)
  readonly onDismiss?: () => void

  close () {
    this.$emit('close')
  }

  confirm () {
    this.close()
    this.onConfirm?.()
  }

  dismiss () {
    this.close()
    this.onDismiss?.()
  }
}
</script>
