<template>
  <Dialog
    class="lassox-diagram__SyncDialog"
    :size="640"
    :dismissable="true"
    title="Opdater diagram"
    :loading="loading"
    :onClose="close"
  >
    <template v-slot:content>
      <div
        v-if="description"
        style="margin: -4px 0; margin-bottom: 20px"
        v-text="description"
      />

      <div v-if="changes.length">
        <SyncDialogChange
          v-for="(change, i) in changes"
          :key="i"
          :change="change"
        />
      </div>

      <div
        v-else-if="!loading"
        style="margin: -2px 0;"
        v-text="'Ingen opdateringer fundet'"
      />
    </template>

    <template v-slot:actions>
      <CheckBoxField
        label="Bevar layout"
        :disabled="loading || !canConfirm"
        style="margin-right: 16px"
        :checked="!runLayout"
        @change="checked => runLayout = !checked"
      />

      <div style="margin: auto" />

      <ButtonGroup align="right">
        <Button
          label="Fortryd"
          :disabled="loading"
          @click="close"
        />

        <Button
          label="Opdater"
          type="primary"
          :disabled="loading || !canConfirm"
          @click="confirm"
        />
      </ButtonGroup>
    </template>
  </Dialog>
</template>

<script lang="ts">
import { Component, Inject } from 'vue-property-decorator'
import DiagramVue from '../DiagramVue'
import Dialog from './Dialog.vue'
import SyncDialogChange, { SyncChange } from './SyncDialogChange.vue'
import SyncDialogChangeItem from './SyncDialogChangeItem.vue'
import CheckBoxField from './CheckBoxField.vue'
import Collapsible from './Collapsible.vue'
import Icon from './Icon.vue'
import IconButton from './IconButton.vue'
import ButtonGroup from './ButtonGroup.vue'
import Button from './Button.vue'
import type DiagramVm from './Diagram.vue'
import type { Entity, EntityDefinition, EntityType, Relation, RelationDefinition, RelationType } from '../diagram'
import type { DataChangeField } from '../types/DiagramUpdater'

@Component({
  components: {
    Dialog,
    SyncDialogChange,
    SyncDialogChangeItem,
    CheckBoxField,
    Collapsible,
    IconButton,
    Icon,
    ButtonGroup,
    Button,
  },
})

export default class SyncDialog extends DiagramVue {
  @Inject()
  readonly diagramVm!: DiagramVm

  get diagram () {
    return this.diagramVm.diagram
  }

  loading = true

  additionChanges: SyncChange[] = []
  removalChanges: SyncChange[] = []
  dataChanges: SyncChange[] = []
  changes: SyncChange[] = []

  runLayout = true

  get description () {
    return this.diagram.updater.dialog.description
  }

  get canConfirm () {
    return this.changes.some(change => change.checked)
  }

  createAdditionChanges () {
    const { activeDiagram } = this.diagram
    const getEntityType = (id: string) => this.diagram.entityTypes.get(id)
    const getRelationType = (id: string) => this.diagram.relationTypes.get(id)
    const { updater } = activeDiagram

    const changes: SyncChange[] = []

    for (const addition of updater.additions) {
      const getEntityLabel = (id: string) => {
        const entity = activeDiagram.data.entitiesMap.get(id)
        if (entity) return entity.label

        const additionEntity = addition.entities.get(id)
        if (!additionEntity) return id

        const { type, data } = additionEntity.entity
        return (data && getEntityType(type).labels.entityLabel?.({ data })) ?? id
      }

      const change: SyncChange = {
        get checked () { return addition.checked },
        set checked (checked) { addition.checked = checked },
        type: 'addition',
        addition,
        items: [],
        expanded: false,
      }

      const getBase = <Type extends EntityType | RelationType, Def extends EntityDefinition | RelationDefinition> (type: Type, item: { definition: Def, fields: DataChangeField[], previouslyDeleted: boolean }) => {
        const { definition, fields, previouslyDeleted } = item
        return {
          isEntity: false as const,
          isRelation: false as const,
          type,
          id: definition.id,
          definition,
          fields: fields.filter(field => field.newValueLabel),
          previouslyDeleted,
          expanded: false,
        }
      }

      const entityTypeCounts = new Map<EntityType, number>()
      const rootEntities = new Set<Entity>()

      for (const [ id, { entity, fields, previouslyDeleted } ] of addition.entities) {
        const type = getEntityType(entity.type)

        change.items.push({
          ...getBase(type, { definition: entity, fields, previouslyDeleted }),
          isEntity: true,
          label: getEntityLabel(id),
        })

        entityTypeCounts.set(type, (entityTypeCounts.get(type) ?? 0) + 1)
      }

      for (const [ id, { relation, fields, previouslyDeleted } ] of addition.relations) {
        const type = getRelationType(relation.type)

        change.items.push({
          ...getBase(type, { definition: relation, fields, previouslyDeleted }),
          isRelation: true,
          label: type.labels.singular,
          fromEntityLabel: getEntityLabel(relation.from),
          toEntityLabel: getEntityLabel(relation.to),
        })

        for (const id of [ relation.from, relation.to ]) {
          const entity = activeDiagram.data.entitiesMap.get(id)
          if (entity) rootEntities.add(entity)
        }
      }

      change.newLabel = entityTypeCounts.size ? {
        entityTypeCounts: [ ...entityTypeCounts ],
        relatedEntityLabels: [ ...rootEntities ].map(entity => getEntityLabel(entity.id)),
      } : undefined

      changes.push(change)
    }

    return changes
  }

  createRemovalChanges () {
    const { activeDiagram } = this.diagram
    const { updater } = activeDiagram

    const changes: SyncChange[] = []

    for (const removal of updater.removals) {
      const change: SyncChange = {
        get checked () { return removal.checked },
        set checked (checked) { removal.checked = checked },
        type: 'removal',
        removal,
        items: [],
        expanded: false,
      }

      const getBase = <T extends Entity | Relation> (element: T, isCustom: boolean, fields: DataChangeField[]) => {
        return {
          isEntity: false as const,
          isRelation: false as const,
          type: element.type as T['type'],
          id: element.id,
          isCustom,
          fields: fields.filter(field => field.currentValueLabel || field.currentInitialValueLabel),
          expanded: false,
        }
      }

      for (const { entity, isCustom, fields } of removal.entities.values()) {
        change.items.push({
          ...getBase(entity, isCustom, fields),
          isEntity: true,
          label: entity.label,
        })
      }

      for (const { relation, isCustom, fields } of removal.relations.values()) {
        change.items.push({
          ...getBase(relation, isCustom, fields),
          isRelation: true,
          label: relation.type.labels.singular,
          fromEntityLabel: relation.fromEntity?.label ?? '',
          toEntityLabel: relation.toEntity?.label ?? '',
        })
      }

      changes.push(change)
    }

    return changes
  }

  createDataChanges () {
    const { activeDiagram } = this.diagram
    const { updater } = activeDiagram

    const changes: SyncChange[] = []

    for (const dataChange of updater.dataChanges) {
      const change: SyncChange = {
        get checked () { return dataChange.checked },
        set checked (checked) { dataChange.checked = checked },
        type: 'dataChange',
        dataChange,
        items: [],
        expanded: false,
      }

      const getBase = <T extends Entity | Relation> (element: T, fields: DataChangeField[]) => {
        return {
          isEntity: false as const,
          isRelation: false as const,
          type: element.type as T['type'],
          id: element.id,
          fields: fields,
          expanded: false,
        }
      }

      for (const { entity, fields } of dataChange.entities.values()) {
        change.items.push({
          ...getBase(entity, fields),
          isEntity: true,
          label: entity.label,
        })
      }

      for (const { relation, fields } of dataChange.relations.values()) {
        change.items.push({
          ...getBase(relation, fields),
          isRelation: true,
          label: relation.type.labels.singular,
          fromEntityLabel: relation.fromEntity?.label ?? '',
          toEntityLabel: relation.toEntity?.label ?? '',
        })
      }

      changes.push(change)
    }

    return changes
  }

  async created () {
    const { activeDiagram } = this.diagram
    const { updater } = activeDiagram

    this.loading = true

    this.runLayout = this.diagram.userPreferences.runLayoutAfterAddition

    if (!await updater.load()) {
      this.close()
      return
    }

    this.additionChanges = this.createAdditionChanges()
    this.removalChanges = this.createRemovalChanges()
    this.dataChanges = this.createDataChanges()

    this.changes = [
      ...this.additionChanges,
      ...this.removalChanges,
      ...this.dataChanges,
    ]

    if (!this.changes.length) {
      this.close()
      this.diagram.store.showToast({ content: 'Ingen opdateringer fundet' })
      return
    }

    this.loading = false
  }

  close () {
    this.$emit('close')
  }

  confirm () {
    this.diagram.activeDiagram.updater.commit(this.runLayout)

    if (this.runLayout !== this.diagram.userPreferences.runLayoutAfterAddition) {
      this.diagram.userPreferences.runLayoutAfterAddition = this.runLayout
    }

    this.close()
  }
}
</script>

<style lang="scss">
.lassox-diagram__SyncDialog {
  .lassox-diagram__Dialog-actions {
    display: flex;
    align-items: center;
  }
}
</style>
