<template>
  <Dialog
    class="lassox-diagram__AddEntityDialog"
    :dismissable="true"
    title="Tilføj"
    size="2x"
    :onClose="close"
  >
    <template v-slot:content>
      <EntitySelector
        ref="entitySelector"
        @change="model => entitySelectorModel = model"
      />
    </template>

    <template v-slot:actions>
      <ButtonGroup align="right">
        <Button
          label="Fortryd"
          @click="close"
        />

        <Button
          label="Tilføj"
          type="primary"
          :disabled="!canConfirm"
          @click="confirm"
        />
      </ButtonGroup>
    </template>
  </Dialog>
</template>

<script lang="ts">
import { Vue, Component, Inject, Prop, Ref } from 'vue-property-decorator'
import Dialog from './Dialog.vue'
import EntitySelector, { EntitySelectorModel } from './EntitySelector.vue'
import ButtonGroup from './ButtonGroup.vue'
import Button from './Button.vue'
import type DiagramVm from './Diagram.vue'
import type { Position } from 'cytoscape'
import type { EntityDefinition } from '../diagram'
import _cloneDeep from 'lodash.clonedeep'
import _merge from 'lodash.merge'

@Component({
  components: {
    Dialog,
    EntitySelector,
    ButtonGroup,
    Button,
  },
})

export default class AddEntityDialog extends Vue {
  @Inject()
  readonly diagramVm!: DiagramVm

  @Ref()
  readonly entitySelector!: EntitySelector

  @Prop({ type: Object, required: false })
  readonly position?: Position

  isConfirming = false

  entitySelectorModel: EntitySelectorModel = null

  get diagram () {
    return this.diagramVm.diagram
  }

  get canConfirm () {
    if (this.isConfirming) return false
    if (!this.entitySelectorModel) return false
    if (this.entitySelectorModel.mode === 'search' && this.entitySelectorModel.selectedSuggestion.entity) return false
    return true
  }

  close () {
    this.$emit('close')
  }

  async confirm () {
    const { canConfirm, entitySelectorModel } = this

    if (!canConfirm || !entitySelectorModel) return

    this.isConfirming = true

    const generateId = (prefix: string, items: Map<string, any>) => {
      const time = Date.now()
      let i = 0
      let id = ''
      while (!id || items.has(id)) {
        id = `${prefix}-${time}-${i}`
        i++
      }
      return id
    }

    let entityId: string
    let newEntity: EntityDefinition

    if (entitySelectorModel.mode === 'search') {
      const suggestion = entitySelectorModel.selectedSuggestion

      entityId = suggestion.id

      if (suggestion.entityDefinition) {
        newEntity = _cloneDeep(suggestion.entityDefinition)

        if (this.diagram.methods.getEntityData) {
          // TODO : We could add actual handling here instead of ignoring the error.

          const data = await this.diagram.methods.getEntityData({
            ids: [ suggestion.id ],
            relationTypes: [],
            parents: 0,
            children: 0,
            onDate: this.diagram.activeDiagram.historicalDate,
          }).catch(err => {
            console.error('getEntityData() failed', err)
            this.diagram.store.showToast({ content: `Vi kunne ikke hente data for "${suggestion.text}"` })
            return null
          })

          const entity = data?.entities?.find(e => e.id === suggestion.id)

          if (entity) newEntity = _merge(newEntity, entity)
        }
      } else {
        throw Error('AddEntityDialog cannot be used to add an entity that is already in the diagram')
      }
    } else {
      entityId = generateId('CUSTOM-ENTITY', this.diagram.activeDiagram.data.entitiesMap)

      newEntity = {
        type: entitySelectorModel.entityType.id,
        id: entityId,
        data: entitySelectorModel.entityData,
      }
    }

    if (this.position) newEntity.position = this.position

    if (!this.entitySelector.validate({
      isEntity: true,
      isRelation: false,
      type: newEntity.type,
      id: newEntity.id,
      data: newEntity.data || {},
      isParent: false,
      isChild: false,
      activeLayout: this.diagram.activeDiagram.settings.activeLayout,

      isMainEntity: false,
      connectedRelations: [],
      incomingRelations: [],
      outgoingRelations: [],

      fromEntity: null,
      toEntity: null,
      connectedEntities: [],
    })) {
      this.isConfirming = false
      return
    }

    this.diagram.activeDiagram.data.add({
      entities: [ newEntity ],
    })

    this.close()
  }
}
</script>
