<template>
  <div
    :class="[
      'lassox-diagram__TabBar',
      outlined && 'lassox-diagram__TabBar--outlined',
    ]"
  >
    <div class="lassox-diagram__TabBar_outline" />

    <div class="lassox-diagram__TabBar_tabs-wrapper">
      <BaseButton
        v-for="tab in tabs"
        :key="tab.id"
        :class="[
          'lassox-diagram__TabBar_tab',
          tab === activeTab && 'lassox-diagram__TabBar_tab--active',
        ]"
        :label="tab.label"
        @click="activeTab = tab"
      />
    </div>
  </div>
</template>

<script lang="ts">
import { Vue, Component, Prop, Model } from 'vue-property-decorator'
import BaseButton from './BaseButton.vue'

interface Tab {
  id: string
  label: string
}

@Component({
  components: {
    BaseButton,
  },
})

export default class TabBar extends Vue {
  @Prop({ type: Array, required: true })
  readonly tabs!: Tab[]

  @Model('change', { type: String })
  readonly activeTabId?: string

  @Prop(Boolean)
  readonly outlined?: boolean

  get tabsMap () {
    return new Map(this.tabs.map(tab => [ tab.id, tab ]))
  }

  get activeTab () {
    return this.tabsMap.get(this.activeTabId ?? '')
  }

  set activeTab (tab: Tab | undefined) {
    if (tab?.id === this.activeTabId) return
    this.$emit('change', tab?.id)
  }
}
</script>

<style lang="scss">
.lassox-diagram__TabBar {
  position: relative;
  overflow: hidden;

  &_tabs-wrapper {
    position: relative;
    display: flex;
  }

  &_tab {
    width: 1px;
    flex-grow: 1;
    flex-shrink: 0;
    height: 36px;
    padding: 0 12px;
    transition-property: color, background-color;
    transition-duration: 100ms;

    &--active {
      color: #ffa07a;
      background-color: rgba(#ffa07a, 0.16);

      .lassox-diagram__BaseButton_overlay {
        background-color: rgba(#ffa07a, 0.32);
      }
    }
  }

  &--outlined {
    border-radius: 2px;
  }

  &--outlined &_outline {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    border-radius: inherit;
    pointer-events: none;
    box-shadow: inset 0 0 0 1px rgba(black, 0.12);
  }
}
</style>
