<template>
  <div
    class="lassox-diagram__CustomizerFieldGroupDropdownButton"
  >
    <BaseButton
      ref="button"
      class="lassox-diagram__CustomizerFieldGroupDropdownButton_button"
      :label="fieldGroup.title"
      :trailingIcon="showDropdownMenu ? 'expand_less' : 'expand_more'"
      @click="() => showDropdownMenu = !showDropdownMenu"
    />

    <DropdownMenu
      :opener="showDropdownMenu ? buttonEl : null"
      width="opener-width"
      :close="() => showDropdownMenu = false"
    >
      <DropdownMenuItem
        v-for="field in fields"
        :key="field.id"
        :label="field.title"
        :icon="field.active ? 'check_box' : 'check_box_outline_blank'"
        :closeMenuOnClick="false"
        @click="() => field.active = !field.active"
      />
    </DropdownMenu>
  </div>
</template>

<script lang="ts">
import { Vue, Component, Prop, Inject } from 'vue-property-decorator'
import BaseButton from './BaseButton.vue'
import DropdownMenu from './DropdownMenu.vue'
import DropdownMenuItem from './DropdownMenuItem.vue'
import type { default as Diagram, FieldGroup } from '../diagram'

@Component({
  components: {
    BaseButton,
    DropdownMenu,
    DropdownMenuItem,
  },
})

export default class CustomizerFieldGroupDropdownButton extends Vue {
  @Inject()
  readonly diagram!: Diagram

  @Prop({ type: Object, required: true })
  readonly fieldGroup!: FieldGroup

  showDropdownMenu = false
  buttonEl: HTMLElement | null = null

  get fields () {
    return this.fieldGroup.fields.filter(field => field.display)
  }

  mounted () {
    this.buttonEl = (this.$refs.button as Vue).$el as HTMLElement
  }

  beforeDestroy () {
    this.showDropdownMenu = false
  }
}
</script>

<style lang="scss">
.lassox-diagram__CustomizerFieldGroupDropdownButton {
  margin: -6px 0;

  &_button {
    &.lassox-diagram__BaseButton {
      width: 100%;
      height: 32px;
      padding: 0 8px;
      border-radius: 2px;

      height: auto;
      padding: 6px 8px;
      padding-left: 24px;
      // padding-right: 24px;
    }

    .lassox-diagram__BaseButton {
      &_label {
        flex-grow: 1;
        color: rgba(black, 0.87);
        font-size: 14px;
        line-height: 16px;
        font-weight: 500;

        font-size: 12px;
        line-height: 12px;
      }

      &_trailing-icon {
        margin: -3px 0;
      }
    }
  }
}
</style>
