import Vue from 'vue'
import DiagramVm from './components/Diagram.vue'
import DiagramEventBus from './types/DiagramEventBus'
import DiagramData, { DiagramDataDefinition, Change } from './types/DiagramData'
import { getDeep, setDeep } from './util/get-deep-property'
import SavedDiagram, { createSavedDiagram } from './types/SavedDiagram'
import { isRecord } from './util/type-guards'
import { merge, cloneDeep } from 'lodash'
import { mapGetOrSet } from './util/map-util'
import DiagramUpdater from './types/DiagramUpdater'
import { createStore, Store } from './store'
import ConfirmAdditionDialog from './components/ConfirmAdditionDialog.vue'

export default class Diagram {
  static init (config: DiagramConfig) {
    return new Diagram(config)
  }

  static defaultGraphCache = new Map<string, Promise<DiagramDataDefinition | null>>()

  store: Store

  element?: Element
  vm?: Vue

  eventBus = new DiagramEventBus()

  userId: string
  mainEntityId: string

  initialSavedDiagram: SavedDiagram | null

  entityTypes: EntityTypes
  relationTypes: RelationTypes

  fieldGroups: FieldGroup[]
  fields: Field[]

  filters: Filter[]

  layouts: LayoutDefinition[]

  methods: DiagramConfigMethods

  spreadTaxiEdges: boolean
  initialZoomLevel: number | null
  initialPan: NonNullable<DiagramConfig['initialPan']> | null
  fitOnResize: boolean
  compactWidth: number
  dragAndDropGridSize: number
  hideDanglingEntitiesAfterFilter: boolean

  enableTopBar = true
  enableCustomizer = true
  enableZoom = true
  enableEditing = false
  enableStyleEditing = false
  showInactiveEditorFields = false
  enableDragAndDrop = false
  enableTaxiEditing = false
  enableExpand = false
  enableSaving = false
  enableDocuments = false
  enableSharing = false
  enableHistoricalDatePicker = false
  updater = {
    enabled: false,
    dialog: {
      description: '',
    },
  }
  printSettings: {
    orientation?: 'portrait' | 'landscape'
    size?: 'A5' | 'A4' | 'A3'
    fitToPaper?: boolean
    includeMargin?: boolean
    hideLogo?: boolean
  } = {}
  saveSettingsToLocalStorage: boolean

  userPreferences: UserPreferences

  isLoading = false

  loadSavedDiagramsPromise: Promise<SavedDiagram[]> | null = null
  savedDiagrams: SavedDiagram[] = []
  savedDiagramsMap = new Map<string, SavedDiagram>()
  defaultDiagram: {
    new?: boolean
    savedDiagramId?: string
  } = {}

  activeDiagram: ActiveDiagram
  hasActiveDiagram = false

  hasUnsavedChanges = false
  hasSavedSinceLoad = false
  isSaving = false

  constructor (config: DiagramConfig) {
    this.userId = config.userId ?? ''
    this.mainEntityId = config.mainEntityId

    this.initialSavedDiagram = config.savedDiagram ?? null

    this.entityTypes = new EntityTypes(config.entityTypes ?? [])
    this.relationTypes = new RelationTypes(config.relationTypes ?? [])

    this.fieldGroups = config.fieldGroups?.map(f => new FieldGroup(this, f)) ?? []
    this.fields = this.fieldGroups.flatMap(fieldGroup => fieldGroup.fields)

    this.filters = config.filters?.map(f => new Filter(this, f)) ?? []

    this.layouts = config.layouts ?? []

    this.methods = {
      getSavedDiagrams: config.methods?.getSavedDiagrams,

      loadSavedDiagram: config.methods?.loadSavedDiagram,
      saveDiagram: config.methods?.saveDiagram,
      deleteSavedDiagram: config.methods?.deleteSavedDiagram,

      getDefaultDiagram: config.methods?.getDefaultDiagram,
      setDefaultDiagram: config.methods?.setDefaultDiagram,

      getUserPreferences: config.methods?.getUserPreferences,
      setUserPreferences: config.methods?.setUserPreferences,

      getPrintTitle: config.methods?.getPrintTitle,
      getPrintFilename: config.methods?.getPrintFilename,
      convertPngToPdf: config.methods?.convertPngToPdf,

      getEntityData: config.methods?.getEntityData,

      searchEntities: config.methods?.searchEntities,

      getContextMenuActions: config.methods?.getContextMenuActions,

      openFullscreen: config.methods?.openFullscreen,
    }

    this.spreadTaxiEdges = config.spreadTaxiEdges ?? false
    this.initialZoomLevel = config.initialZoomLevel ?? null
    this.initialPan = config.initialPan ?? null
    this.fitOnResize = config.fitOnResize ?? true
    this.compactWidth = config.compactWidth ?? 767
    this.dragAndDropGridSize = config.dragAndDropGridSize ?? 0
    this.hideDanglingEntitiesAfterFilter = config.hideDanglingEntitiesAfterFilter ?? true

    this.enableCustomizer = config.enableCustomizer ?? true
    this.enableTopBar = config.enableTopBar ?? true
    this.enableZoom = config.enableZoom ?? true
    if (config.enableEditing) this.enableEditing = true
    if (config.enableStyleEditing) this.enableStyleEditing = true
    if (config.showInactiveEditorFields) this.showInactiveEditorFields = true
    if (config.enableDragAndDrop) this.enableDragAndDrop = true
    if (config.enableTaxiEditing) this.enableTaxiEditing = true
    if (config.enableExpand) this.enableExpand = true

    if (config.enableSaving) {
      this.enableSaving = true

      if (!config.methods?.saveDiagram) {
        console.warn('Cannot enable saving without providing a saveDiagram method.')
        this.enableSaving = false
      }
    }

    if (config.enableDocuments) this.enableDocuments = true
    if (config.enableSharing) this.enableSharing = true
    if (config.enableHistoricalDatePicker) this.enableHistoricalDatePicker = true

    if (config.updater?.enabled) {
      if (!config.methods?.getEntityData) {
        console.warn('Cannot enable updater without providing a getEntityData method.')
      } else {
        this.updater.enabled = true

        if (config.updater.dialog) {
          this.updater.dialog.description = config.updater.dialog.description ?? this.updater.dialog.description
        }
      }
    }

    if (config.printSettings) {
      this.printSettings.orientation = config.printSettings.orientation
      this.printSettings.size = config.printSettings.size
      this.printSettings.fitToPaper = config.printSettings.fitToPaper
      this.printSettings.includeMargin = config.printSettings.includeMargin
      this.printSettings.hideLogo = config.printSettings.hideLogo ?? false
    }

    this.saveSettingsToLocalStorage = config.saveSettingsToLocalStorage ?? false

    for (const entityType of this.entityTypes.items) {
      entityType.fieldGroups = this.fieldGroups.map(fg => new FieldGroup(this, {
        ...fg,
        fields: fg.fields.filter(f => f.entityTypes.has(entityType)),
      }))

      entityType.fields = entityType.fieldGroups.flatMap(fg => fg.fields)
      entityType.searchableFields = entityType.fields.filter(field => field.searchable)
    }

    for (const relationType of this.relationTypes.items) {
      relationType.fieldGroups = this.fieldGroups.map(fg => new FieldGroup(this, {
        ...fg,
        fields: fg.fields.filter(f => f.relationTypes.has(relationType)),
      }))

      relationType.fields = relationType.fieldGroups.flatMap(fg => fg.fields)
      relationType.searchableFields = relationType.fields.filter(field => field.searchable)

      for (const support of relationType.supports) {
        const fromType = this.entityTypes.get(support.from)
        const toType = this.entityTypes.get(support.to)

        const [
          fromSupportedRelations,
          toSupportedRelations,
        ] = ([ fromType, toType ]).map(entityType => mapGetOrSet(entityType.supportedRelations, relationType.id, () => ({
          type: relationType,
          supports: [],
          supportsParent: false,
          supportsAddExistingParents: false,
          supportsChild: false,
          supportsAddExistingChildren: false,
        })))

        fromSupportedRelations.supports.push(support)
        if (toType !== fromType) toSupportedRelations.supports.push(support)
      }
    }

    for (const entityType of this.entityTypes.items) {
      for (const supportedRelation of entityType.supportedRelations.values()) {
        for (const support of supportedRelation.supports) {
          if (
            supportedRelation.supportsParent
            && supportedRelation.supportsAddExistingParents
            && supportedRelation.supportsChild
            && supportedRelation.supportsAddExistingChildren
          ) break

          if (support.to == entityType.id) {
            supportedRelation.supportsParent = true
            if (support.allowAddExisting) supportedRelation.supportsAddExistingParents = true
          }

          if (support.from == entityType.id) {
            supportedRelation.supportsChild = true
            if (support.allowAddExisting) supportedRelation.supportsAddExistingChildren = true
          }
        }
      }
    }

    this.userPreferences = new UserPreferences(this)

    this.activeDiagram = new ActiveDiagram(this)

    this.eventBus.on('dataUpdated', () => {
      this.activeDiagram.updater.updateCacheKeys()
      this.activeDiagram.updater.loadIfCached()
    })

    this.eventBus.on([ 'dataUpdated', 'settingsChanged' ], () => {
      this.hasUnsavedChanges = true
    })

    this.store = createStore({ diagram: this })
  }

  render (container: Element) {
    if (this.element) this.element.parentElement?.removeChild(this.element)
    if (this.vm) this.vm.$destroy()

    const element = document.createElement('div')
    container.appendChild(element)

    this.element = element
    this.vm = new Vue({
      el: element,
      render: h => h(DiagramVm, {
        props: {
          diagram: Vue.observable(this),
        },
      }),
    })

    return element
  }

  setActiveDiagram (activeDiagram: ActiveDiagram) {
    this.activeDiagram = activeDiagram
    this.hasActiveDiagram = true
    this.eventBus.emit({ name: 'settingsChanged' })
    this.hasUnsavedChanges = false
    this.hasSavedSinceLoad = false
  }

  async loadSavedDiagrams () {
    const { getSavedDiagrams } = this.methods
    if (!getSavedDiagrams) return

    const loadSavedDiagramsPromise = this.loadSavedDiagramsPromise = getSavedDiagrams()
    const getDefaultDiagramPromise = this.getDefaultDiagram()

    const [ savedDiagrams ] = await Promise.all([ loadSavedDiagramsPromise, getDefaultDiagramPromise ])

    if (loadSavedDiagramsPromise !== this.loadSavedDiagramsPromise) return

    this.loadSavedDiagramsPromise = null

    this.savedDiagrams = savedDiagrams
    this.savedDiagramsMap.clear()

    for (const savedDiagram of savedDiagrams) {
      this.savedDiagramsMap.set(savedDiagram.id, savedDiagram)
    }
  }

  async getDefaultDiagram () {
    if (this.methods.getDefaultDiagram) {
      return this.defaultDiagram = await this.methods.getDefaultDiagram()
    }

    if (this.saveSettingsToLocalStorage) {
      try {
        const json = localStorage.getItem(`lassox-diagram/default-diagram-for-${this.mainEntityId}`)

        try {
          const parsed = json && JSON.parse(json)

          if (isRecord<'new' | 'savedDiagramId'>(parsed)) {
            if (parsed.new) {
              return this.defaultDiagram = { new: true }
            }

            if (typeof parsed.savedDiagramId === 'string') {
              return this.defaultDiagram = { savedDiagramId: parsed.savedDiagramId }
            }
          }
        } catch {
          if (json) {
            return this.defaultDiagram = { savedDiagramId: json }
          }
        }
      } catch {
        // ...
      }
    }

    return this.defaultDiagram = {}
  }

  async setDefaultDiagram (defaultDiagram: Diagram['defaultDiagram']) {
    this.defaultDiagram = defaultDiagram

    if (this.methods.setDefaultDiagram) {
      await this.methods.setDefaultDiagram(defaultDiagram)
      return
    }

    if (this.saveSettingsToLocalStorage) {
      try {
        if (defaultDiagram) {
          localStorage.setItem(`lassox-diagram/default-diagram-for-${this.mainEntityId}`, JSON.stringify(defaultDiagram))
          return
        }

        localStorage.removeItem(`lassox-diagram/default-diagram-for-${this.mainEntityId}`)
      } catch {
        // ...
      }
    }
  }

  async save (overwrite = true) {
    const { saveDiagram } = this.methods

    if (this.isSaving || !saveDiagram) return

    this.isSaving = true

    const savedDiagram = createSavedDiagram(this)
    if (!overwrite) {
      savedDiagram.id = ''
      savedDiagram.ownerUserId = this.userId
    }

    try {
      const id = await saveDiagram({
        savedDiagram,
        isActiveDiagram: true,
        generatePng: options => this.generatePng(options),
      })

      if (id) this.activeDiagram.id = id

      await this.loadSavedDiagrams()

      this.hasUnsavedChanges = false
      this.isSaving = false
      this.hasSavedSinceLoad = true
    } catch (error) {
      this.isSaving = false

      throw error
    }
  }

  async updateSavedDiagram (savedDiagram: SavedDiagram) {
    const { saveDiagram } = this.methods

    if (!saveDiagram || !savedDiagram.id) return

    await saveDiagram({
      savedDiagram,
      isActiveDiagram: false,
      generatePng: () => {
        throw Error('generatePng() is only callable for the active diagram. Check "context.isActiveDiagram" in the saveDiagram method before calling generatePng()')
      },
    })
  }

  async generatePng (options?: GeneratePngOptions) {
    const promise = new Promise<Blob>(resolve => this.eventBus.one('printDone', ({ file }) => {
      if (!file) throw Error('printDone did not return a file')
      resolve(file.blob)
    }))

    this.eventBus.emit({
      name: 'print',
      mode: 'png',
      paper: false,
      includeMargin: false,

      paperOrientation: options?.paperOrientation,
      paperSize: options?.paperSize,

      width: options?.width,
      height: options?.height,

      grow: options?.grow,

      scaling: options?.scaling,
    })

    return await promise
  }

  async loadSavedDiagram (savedDiagram: SavedDiagram) {
    const { loadSavedDiagram } = this.methods

    if (loadSavedDiagram) savedDiagram = await loadSavedDiagram(savedDiagram)

    const activeDiagram = new ActiveDiagram(this, {
      id: savedDiagram.id,
      ownerUserId: savedDiagram.ownerUserId,
      title: savedDiagram.title,
      description: savedDiagram.description,
      shared: savedDiagram.shared,

      data: new DiagramData(this, {
        data: savedDiagram.data,
        changes: savedDiagram.changes,
      })
    })

    if (savedDiagram.settings) {
      const { settings } = activeDiagram

      if (savedDiagram.settings.activeFields) {
        for (const id in settings.activeFields) {
          settings.activeFields[id] = false
        }

        for (const id of savedDiagram.settings.activeFields) {
          if (id in settings.activeFields) settings.activeFields[id] = true
        }
      }

      if (savedDiagram.settings.activeFilters) {
        for (const id in settings.activeFilters) {
          settings.activeFilters[id] = false
        }

        for (const id of savedDiagram.settings.activeFilters) {
          if (id in settings.activeFilters) settings.activeFilters[id] = true
        }
      }

      if (savedDiagram.settings.activeLayout) {
        const id = savedDiagram.settings.activeLayout
        const layout = this.layouts.find(l => l.id === id)
        if (layout) settings.setActiveLayout(layout)
      }

      if (savedDiagram.settings.enableTaxi !== undefined) {
        settings.setEnableTaxi(savedDiagram.settings.enableTaxi)
      }

      settings.setInitialState()
    }

    this.setActiveDiagram(activeDiagram)

    activeDiagram.updater.load()
  }

  async loadNewDiagram (options: {
    onDate?: Date | null
  } = {}) {
    const {
      onDate = null,
    } = options

    this.isLoading = true

    let data: DiagramData | undefined = undefined

    if (this.methods.getEntityData) {
      const responseData = await this.fetchDefaultGraph({ onDate })

      if (responseData) {
        data = new DiagramData(this, { data: responseData })
      } else {
        this.store.showToast({ content: 'Noget gik galt ved indlæsning af diagrammet.' })
      }
    }

    const activeDiagram = new ActiveDiagram(this, {
      ownerUserId: this.userId,
      data,
      settings: this.userPreferences.settings.clone(),
      historicalDate: onDate,
    })

    this.setActiveDiagram(activeDiagram)
    this.isLoading = false

    activeDiagram.updater.loaded = true
  }

  async load (savedDiagram?: SavedDiagram) {
    if (savedDiagram) await this.loadSavedDiagram(savedDiagram)
    else await this.loadNewDiagram()
  }

  async deleteSavedDiagram (savedDiagram: SavedDiagram) {
    const { deleteSavedDiagram } = this.methods
    if (!deleteSavedDiagram || !savedDiagram.id) return

    await deleteSavedDiagram(savedDiagram)
    await this.loadSavedDiagrams()
  }

  reset () {
    this.activeDiagram.reset()
    this.eventBus.emit({ name: 'settingsChanged' })
    this.eventBus.emit({ name: 'activeFieldsChanged' })
    this.eventBus.emit({ name: 'activeFiltersChanged' })
    this.eventBus.emit({ name: 'graph.fit' })
    this.hasUnsavedChanges = this.hasSavedSinceLoad
  }

  search (type: EntityType, searchString: string): Entity[]

  search (type: RelationType, searchString: string): Relation[]

  search (type: EntityType | RelationType, searchString: string): (Entity | Relation)[] {
    searchString = searchString.trim().toLowerCase()

    if (!searchString || !type.searchable || !type.searchableFields.length) return []

    const results: (Entity | Relation)[] = []

    for (const item of this.activeDiagram.data[type instanceof EntityType ? 'entities' : 'relations']) {
      if (item.type !== type) continue

      for (const field of type.searchableFields) {
        const value = field.getValue(item.data)
        const string = (`${(field.formatter ? field.formatter(value) : value) ?? ''}`).trim().toLowerCase()

        if (string && string.includes(searchString)) {
          results.push(item)
          break
        }
      }
    }

    return results
  }

  async fetchDefaultGraph (options: {
    onDate?: Date | null
  } = {}) {
    const {
      onDate = null,
    } = options

    const useCache = onDate === null

    const cacheKey = this.mainEntityId

    if (useCache) {
      const cached = Diagram.defaultGraphCache.get(cacheKey)
      if (cached) return cached
    }

    const promise = this.methods.getEntityData?.({
      ids: [ this.mainEntityId ],
      relationTypes: this.relationTypes.items.map(rt => rt.id),
      parents: 10,
      children: 10,
      onDate,
    }).catch(err => {
      console.error('getEntityData() failed', err)
      if (useCache) {
        Diagram.defaultGraphCache.delete(cacheKey)
      }
      return null
    }) ?? Promise.resolve(null)

    if (useCache) {
      Diagram.defaultGraphCache.set(cacheKey, promise)
    }

    return promise
  }
}

export interface DiagramConfig {
  userId?: string
  mainEntityId: string
  savedDiagram?: SavedDiagram
  entityTypes?: EntityTypeDefinition[]
  relationTypes?: RelationTypeDefinition[]
  fieldGroups?: FieldGroupDefinition[]
  filters?: FilterDefinition[]
  layouts?: LayoutDefinition[]
  methods?: DiagramConfigMethods
  spreadTaxiEdges?: boolean
  initialZoomLevel?: number
  initialPan?: {
    x?: 'left' | 'center' | 'right'
    y?: 'top' | 'center' | 'bottom'
  }
  fitOnResize?: boolean
  compactWidth?: number
  dragAndDropGridSize?: number
  hideDanglingEntitiesAfterFilter?: boolean
  enableEditing?: boolean
  enableStyleEditing?: boolean
  showInactiveEditorFields?: boolean
  enableDragAndDrop?: boolean
  enableTaxiEditing?: boolean
  enableExpand?: boolean
  enableSaving?: boolean
  enableDocuments?: boolean
  enableSharing?: boolean
  enableTopBar?: boolean
  enableCustomizer?: boolean
  enableZoom?: boolean
  enableHistoricalDatePicker?: boolean
  updater?: {
    enabled?: boolean
    dialog?: {
      description?: string
    }
  }
  printSettings?: {
    orientation?: 'portrait' | 'landscape'
    size?: 'A5' | 'A4' | 'A3'
    fitToPaper?: boolean
    includeMargin?: boolean
    hideLogo?: boolean
  }
  saveSettingsToLocalStorage?: boolean
}

export interface DiagramConfigMethods {
  getSavedDiagrams?: () => Promise<SavedDiagram[]>

  loadSavedDiagram?: (savedDiagram: SavedDiagram) => Promise<SavedDiagram>

  saveDiagram?: (context: {
    savedDiagram: SavedDiagram,
    isActiveDiagram: boolean,
    generatePng: (options?: GeneratePngOptions) => Promise<Blob>,
  }) => Promise<string | void>

  deleteSavedDiagram?: (savedDiagram: SavedDiagram) => Promise<void>

  getDefaultDiagram?: () => Promise<Diagram['defaultDiagram']>
  setDefaultDiagram?: (defaultDiagram: Diagram['defaultDiagram']) => Promise<void>

  getUserPreferences? (): Promise<UserPreferencesDefinition | null>
  getUserPreferences? (): Promise<unknown>

  setUserPreferences?: (userPreferences: UserPreferencesDefinition) => Promise<void>

  getPrintTitle?: (context: PrintContext) => string
  getPrintFilename?: (context: PrintContext) => string

  convertPngToPdf?: (context: {
    blob: Blob,
    title: string,
    filename: string,
    size: 'A5' | 'A4' | 'A3',
    orientation: 'portrait' | 'landscape',
    includeMargin: boolean,
    pageCount: number,
  }) => Promise<Blob>

  getEntityData?: (options: {
    ids: string[], // Entity ids
    relationTypes: string[], // RelationType ids
    parents: number,
    children: number,
    onDate: Date | null,
  }) => Promise<DiagramDataDefinition>

  searchEntities?: (context: {
    query: string // The search query
    type: string // EntityType id
  }) => Promise<EntityDefinition[]>

  getContextMenuActions?: (context: {
    position: { x: number, y: number }
    selectedItems: ContextItem[]
    selectedEntities: ContextItem[]
    selectedRelations: ContextItem[]
    hasSelectedItems: boolean
    onlySelectedItem: ContextItem | null
    commitChange: (change: Change) => void
  }) => ContextMenuActions | { before?: ContextMenuActions, after?: ContextMenuActions }

  openFullscreen?: () => void
}

export interface GeneratePngOptions {
  // Set paper dimensions
  paperOrientation?: 'portrait' | 'landscape'
  paperSize?: 'A5' | 'A4' | 'A3'

  // Set dimensions in pixels (overwrites paper dimensions)
  width?: number
  height?: number

  // Allow the image to grow higher than the base dimensions to fill out more of the image
  grow?: boolean | 'width' | 'height'

  // Set scaling (1-4)
  scaling?: number
}

export interface PrintContext {
  mainEntity: ContextItem
  hasDataChanges: boolean
  hasCustomizedData: boolean
  date: Date
  formattedDate: string
  formattedTime: string
  historicalDate: Date | null
  formattedHistoricalDate: string
}

export type ContextMenuActions = Arrayable<ContextMenuAction | null>[]

export interface ContextMenuAction {
  icon?: string
  iconColor?: string
  label: string
  disabled?: boolean
  submenu?: ContextMenuActions
  onClick?: () => void
}

export class ActiveDiagram {
  constructor (diagram: Diagram, options?: {
    id?: string
    ownerUserId?: string
    title?: string
    description?: string
    shared?: boolean

    data?: DiagramData
    settings?: Settings
    metadata?: Record<string, any>
    historicalDate?: Date | null
  }) {
    this.diagram = diagram

    this.id = options?.id ?? ''
    this.ownerUserId = options?.ownerUserId ?? ''
    this.title = options?.title ?? ''
    this.description = options?.description ?? ''
    this.shared = options?.shared ?? false

    this.data = options?.data ?? new DiagramData(diagram)
    this.settings = options?.settings ?? new Settings(diagram)
    this.metadata = options?.metadata ?? {}
    this.historicalDate = options?.historicalDate ?? null

    this.updater = new DiagramUpdater(this)
  }

  diagram: Diagram

  id: string
  ownerUserId: string
  title: string
  description: string
  shared: boolean

  data: DiagramData
  settings: Settings
  metadata: Record<string, any>
  historicalDate: Date | null

  updater: DiagramUpdater

  expanding = false

  reset () {
    this.data.reset()
    this.settings.reset()
  }

  async expand (entities?: Entity[]) {
    const { enableExpand, methods: { getEntityData } } = this.diagram

    if (!enableExpand || this.expanding || !getEntityData) return

    this.expanding = true

    const entitiesToExpand = (entities ?? this.data.entities).filter(entity => !entity.expanded)

    if (entitiesToExpand.length > 30) {
      this.diagram.store.showToast({ content: 'Der er for mange entiter i diagrammet til at udvide.' })
      this.expanding = false
      return
    }

    const showFullyExpandedToast = () => this.diagram.store.showToast({ content: 'Diagrammet er nu helt udvidet.' })

    if (!entitiesToExpand.length) {
      showFullyExpandedToast()
      this.expanding = false
      return
    }

    const closeLoadingToast = this.diagram.store.showToast({
      content: 'Udvider diagrammet...',
      dismissable: false,
      duration: 0,
      showLoadingSpinner: true,
    })

    let data = await getEntityData({
      ids: entitiesToExpand.map(e => e.id),
      relationTypes: this.diagram.relationTypes.items.map(rt => rt.id),
      parents: 1,
      children: 1,
      onDate: this.historicalDate,
    }).catch(err => {
      console.error('getEntityData() failed', err)
      return null
    })

    if (!data) {
      closeLoadingToast()
      this.diagram.store.showToast({ content: 'Noget gik galt ved udvidelse af diagrammet.' })
      this.expanding = false
      return
    }

    data = {
      entities: data.entities?.filter(entity => !this.diagram.activeDiagram.data.entitiesMap.has(entity.id)),
      relations: data.relations?.filter(relation => !this.diagram.activeDiagram.data.relationsMap.has(relation.id)),
    }

    closeLoadingToast()

    if (!data.entities?.length && !data.relations?.length) {
      showFullyExpandedToast()
      this.expanding = false
      return
    }

    this.diagram.store.showDialog(ConfirmAdditionDialog, {
      data,
      entitiesToMarkAsExpanded: entitiesToExpand,
    })

    this.expanding = false
  }
}

export class EntityTypes {
  constructor (items: EntityTypeDefinition[]) {
    this.items = items.map(item => new EntityType(item))
    this.itemsMap = new Map(this.items.map(item => [item.id, item]))
  }

  items: EntityType[]
  itemsMap: Map<string, EntityType>

  has (idOritem: string | EntityType) {
    return typeof idOritem == 'string'
      ? this.itemsMap.has(idOritem)
      : this.itemsMap.has(idOritem.id)
  }

  get (id: string) {
    const item = this.itemsMap.get(id)
    if (!item) throw Error(`No entity type with id "${id}"`)
    return item
  }

  getMultiple (ids: string[]) {
    return ids.map(id => this.get(id))
  }

  pick (ids: string[]) {
    return new EntityTypes(this.getMultiple(ids))
  }
}

export class RelationTypes {
  constructor (items: RelationTypeDefinition[]) {
    this.items = items.map(item => new RelationType(item))
    this.itemsMap = new Map(this.items.map(item => [item.id, item]))
  }

  items: RelationType[]
  itemsMap: Map<string, RelationType>

  has (idOritem: string | RelationType) {
    return typeof idOritem == 'string'
      ? this.itemsMap.has(idOritem)
      : this.itemsMap.has(idOritem.id)
  }

  get (id: string) {
    const item = this.itemsMap.get(id)
    if (!item) throw Error(`No relation type with id "${id}"`)
    return item
  }

  getMultiple (ids: string[]) {
    return ids.map(id => this.get(id))
  }

  pick (ids: string[]) {
    return new RelationTypes(this.getMultiple(ids))
  }
}

