export interface LayoutDefinition {
  id: string
  name: string
  default?: boolean
  type?: 'breadthfirst' | 'dagre' // defaults to breadthfirst
  taxi?: boolean
  enableTaxiToggle?: boolean

  // general options
  inverted?: boolean
  spacingFactor?: number // positive spacing factor, larger => more space between nodes (N.B. n/a if causes overlap)
  animate?: boolean // whether to transition the node positions
  animationDuration?: number // duration of animation in ms if enabled
  animationEasing?: string // easing of animation if enabled,

  // breadthfirst options
  directed?: boolean // whether the tree is directed downwards (or edges can point in any direction if false)
  grid?: boolean // whether to create an even grid into which the DAG is placed (circle:false only)
  maximal?: boolean // whether to shift nodes down their natural BFS depths in order to avoid upwards edges (DAGS only)

  // dagre options
  nodeSep?: number // the separation between adjacent nodes in the same rank
  edgeSep?: number // the separation between adjacent edges in the same rank
  rankSep?: number // the separation between each rank in the layout
  rankDir?: 'TB' | 'LR' // 'TB' for top to bottom flow, 'LR' for left to right
  align?: 'UL' | 'UR' | 'DL' | 'DR' // alignment for rank nodes. U = up, D = down, L = left, R = right
  ranker?: 'network-simplex' | 'tight-tree' | 'longest-path' // type of algorithm to assign a rank to each node in the input graph
}

export class Settings {
  diagram: Diagram

  initialState: Pick<Settings, 'activeFields' | 'activeFilters' | 'activeLayout' | 'enableTaxi'> = {
    activeFields: {},
    activeFilters: {},
    activeLayout: null,
    enableTaxi: false,
  }

  activeFields: Partial<Record<string, boolean>>
  activeFilters: Partial<Record<string, boolean>>
  activeLayout: LayoutDefinition | null
  enableTaxi: boolean

  constructor (diagram: Diagram) {
    this.diagram = diagram

    const defaults = this.getDefaults()
    this.activeFields = { ...defaults.activeFields }
    this.activeFilters = { ...defaults.activeFilters }
    this.activeLayout = defaults.activeLayout
    this.enableTaxi = defaults.enableTaxi

    this.setInitialState()
  }

  clone () {
    const cloned = new Settings(this.diagram)
    cloned.activeFields = { ...this.activeFields }
    cloned.activeFilters = { ...this.activeFilters }
    cloned.activeLayout = this.activeLayout
    cloned.enableTaxi = this.enableTaxi
    cloned.setInitialState()
    return cloned
  }

  getDefaults () {
    const activeFields: Settings['activeFields'] = {}
    const activeFilters: Settings['activeFilters'] = {}
    let activeLayout: Settings['activeLayout'] = null

    for (const field of this.diagram.fields) {
      activeFields[field.fullId] = field.startActive
    }

    for (const filter of this.diagram.filters) {
      activeFilters[filter.id] = filter.startActive
    }

    if (this.diagram.layouts.length) {
      activeLayout = this.diagram.layouts.find(l => l.default) ?? this.diagram.layouts[0] ?? null
    }

    return {
      activeFields,
      activeFilters,
      activeLayout,
      enableTaxi: activeLayout?.taxi ?? false,
    }
  }

  setInitialState () {
    this.initialState.activeFields = { ...this.activeFields }
    this.initialState.activeFilters = { ...this.activeFilters }
    this.initialState.activeLayout = this.activeLayout
    this.initialState.enableTaxi = this.enableTaxi
  }

  reset () {
    this.activeFields = { ...this.initialState.activeFields }
    this.activeFilters = { ...this.initialState.activeFilters }
    this.activeLayout = this.initialState.activeLayout
    this.enableTaxi = this.initialState.enableTaxi
  }

  setActiveLayout (layout: LayoutDefinition | null) {
    if (layout === this.activeLayout) return
    this.activeLayout = layout
    if (!this.diagram.activeDiagram.id) {
      this.diagram.userPreferences.settings.activeLayout = layout
    }
    this.setEnableTaxi()
  }

  setEnableTaxi (enableTaxi?: boolean) {
    const { activeLayout: layout } = this

    // Don't continue if no layout.
    if (!layout) return

    const set = (value: boolean) => {
      this.enableTaxi = value
      if (!this.diagram.activeDiagram.id) {
        this.diagram.userPreferences.settings.enableTaxi = value
      }
    }

    // If layout doesn't have taxi toggle enabled, use the default value.
    if (!layout.enableTaxiToggle) {
      set(layout.taxi ?? false)
      return
    }

    // If enableTaxi is defined, set this.enableTaxi.
    if (enableTaxi !== undefined) {
      set(enableTaxi)
    }
  }
}

