<template>
  <div class="lassox-diagram__GraphEdgePoints">
    <div
      v-for="(line, i) in n_lines"
      :key="`line-${i}`"
      class="lassox-diagram__GraphEdgePoints-line"
      :style="{
        width: `${line.width}px`,
        height: `${lineHeight}px`,
        padding: `${linePadding}px 0`,
        transformOrigin: 'center left',
        transform: `
          translateY(-50%)
          translate(${line.x}px, ${line.y}px)
          rotate(${line.rotation}deg)
        `,
      }"
      @mousedown="e => {
        if (e.button !== 0) return

        e.preventDefault()
        e.stopPropagation()

        const pos = mousePosToModelPos(e.clientX, e.clientY)

        n_dragging = {
          lines: [ line ],
          offset: {
            x: 0,
            y: 0,
            [line.crossAxis]: line.crossAxisValue - pos[line.crossAxis]
          },
          moved: false,
        }
      }"
      @dblclick="e => onLineDblClick(i, e)"
    />

    <div
      v-for="(point, i) in n_points"
      :key="`point-${i}`"
      class="lassox-diagram__GraphEdgePoints-point"
      :style="{
        width: `${pointSize}px`,
        height: `${pointSize}px`,
        padding: `${pointPadding}px`,
        transform: `
          translate(-50%, -50%)
          translate(${point.x}px, ${point.y}px)
        `,
      }"
      @mousedown="e => {
        if (e.button !== 0) return

        e.preventDefault()
        e.stopPropagation()

        const lines = n_lines.slice(Math.max(i - 1, 0), i + 1)

        const pos = mousePosToModelPos(e.clientX, e.clientY)

        n_dragging = {
          lines,
          offset: {
            x: point.x - pos.x,
            y: point.y - pos.y,
          },
          endpointMode: lines.length === 1,
          moved: false,
        }
      }"
      @dblclick="e => onPointDblClick(i, e)"
    />
  </div>
</template>

<script lang="ts">
import { Vue, Component, Inject } from 'vue-property-decorator'
import type Graph from './Graph.vue'
import type { Core, Position, EdgeSingular, NodeSingular } from 'cytoscape'
import type { default as Diagram, Relation, CustomTaxi, CustomTaxiSegmentPoint } from '../diagram'
import Decimal from 'decimal.js'

type Side = 'top' | 'bottom' | 'left' | 'right'

type Rect = {
  width: number
  height: number
  x: {
    left: number
    center: number
    right: number
  }
  y: {
    top: number
    center: number
    bottom: number
  }
}

type NPoint = {
  x: number
  y: number
  temp?: boolean
}

type NEndpoint = {
  side: Side
  axis: 'x' | 'y'
  x: number
  y: number
}

const snapNumber = (number: number, gridSize: number) => gridSize
  ? new Decimal(number).dividedBy(gridSize).round().times(gridSize).toNumber()
  : number

const clamp = (number: number, min?: number | null, max?: number | null) => {
  if (typeof min === 'number' && number < min) number = min
  if (typeof max === 'number' && number > max) number = max
  return number
}

const getCrossAxis = (axis: 'x' | 'y'): 'x' | 'y' => axis === 'x' ? 'y' : 'x'

const getRectAxisBounds = (axis: 'x' | 'y', rect: Rect) => axis === 'x'
  ? {
    min: rect.x.left,
    max: rect.x.right,
  }
  : {
    min: rect.y.top,
    max: rect.y.bottom,
  }

const getRectPositionSide = (rect: Rect, position: Position): Side => {
  if (position.y === rect.y.top) return 'top'
  if (position.y === rect.y.bottom) return 'bottom'
  if (position.x === rect.x.left) return 'left'
  if (position.x === rect.x.right) return 'right'
  return 'top'
}

const getSideAxis = (side: Side) => side === 'left' || side === 'right' ? 'x' : 'y'

const createCustomTaxiEndpoint = (endpoint: NEndpoint, rect: Rect) => {
  const { side, axis } = endpoint
  const crossAxis = getCrossAxis(endpoint.axis)

  const result = {
    side,
    x: 0,
    y: 0,
  }

  result[axis] = (side === 'top' || side === 'left') ? -0.5 : 0.5

  const crossAxisValue = endpoint[crossAxis]
  let crossAxisMin: number
  let crossAxisMax: number

  if (crossAxis === 'x') {
    crossAxisMin = rect.x.left
    crossAxisMax = rect.x.right
  } else {
    crossAxisMin = rect.y.top
    crossAxisMax = rect.y.bottom
  }

  result[crossAxis] = new Decimal(crossAxisValue).minus(crossAxisMin).dividedBy(new Decimal(crossAxisMax).minus(crossAxisMin)).minus('0.5').toNumber()

  return result
}

const cyUtil = {
  pos: {
    renderedToModel: (cy: Core, pos: Position) => {
      const pan = cy.pan()
      const zoom = cy.zoom()
      return {
        x: (pos.x - pan.x) / zoom,
        y: (pos.y - pan.y) / zoom,
      }
    },
    modelToRendered: (cy: Core, pos: Position) => {
      const pan = cy.pan()
      const zoom = cy.zoom()
      return {
        x: pos.x * zoom + pan.x,
        y: pos.y * zoom + pan.y,
      }
    },
  },
  node: {
    getRect: (node: NodeSingular): Rect => {
      const { x, y } = node.position()
      const width = node.width()
      const height = node.height()
      return {
        width,
        height,
        x: {
          left: x - width / 2,
          center: x,
          right: x + width / 2,
        },
        y: {
          top: y - height / 2,
          center: y,
          bottom: y + height / 2,
        },
      }
    },
  },
}

@Component({})

export default class GraphEdgePoints extends Vue {
  @Inject()
  readonly diagram!: Diagram

  @Inject()
  readonly graphVm!: Graph

  get graph () {
    if (!this.graphVm._graph) throw Error()
    return this.graphVm._graph
  }

  _edge: EdgeSingular | null = null

  lineThickness = 0

  n_sourceEndpoint: NEndpoint | null = null
  n_targetEndpoint: NEndpoint | null = null
  n_points: NPoint[] = []
  n_dragging: {
    lines: GraphEdgePoints['n_lines']
    offset: Position
    endpointMode?: boolean
    moved?: boolean
  } | null = null

  get n_lines () {
    const vm = this

    const {
      n_sourceEndpoint: sourceEndpoint,
      n_targetEndpoint: targetEndpoint,
    } = this

    if (!sourceEndpoint || !targetEndpoint) return []

    const axes: ('x' | 'y')[] = [ 'x', 'y' ]
    if (sourceEndpoint.axis === 'y') axes.reverse()

    const lastI = this.n_points.length - 2

    const lines = this.n_points.slice(0, -1).map((point1, i) => {
      const point2 = this.n_points[i + 1]
      const [ axis, crossAxis ] = axes
      axes.reverse()

      const isFirst = !i
      const isLast = i === lastI

      const endpointName = !i ? 'source' : i === lastI ? 'target' : null
      const endpointNode = endpointName && this._edge?.[endpointName]()

      let crossAxisBounds: Record<'min' | 'max', number | null> | null = null

      if (endpointNode) {
        const rect = cyUtil.node.getRect(endpointNode)
        crossAxisBounds = getRectAxisBounds(crossAxis, rect)
      }

      if (!isFirst && !isLast) {
        const connectedToSource = i === 1
        const connectedToTarget = i === lastI - 1

        if (connectedToSource || connectedToTarget) {
          crossAxisBounds = { min: null, max: null }

          for (const endpoint of [ connectedToSource && sourceEndpoint, connectedToTarget && targetEndpoint ]) {
            if (!endpoint) continue

            const { side } = endpoint
            const boundsKey = (side === 'top' || side === 'left') ? 'max' : 'min'

            let spacing = snapNumber(32, vm.diagram.dragAndDropGridSize)
            if (boundsKey === 'max') spacing *= -1

            const oldValue = crossAxisBounds[boundsKey]
            const value = endpoint[crossAxis] + spacing

            if (oldValue === null) {
              crossAxisBounds[boundsKey] = value
            } else {
              if (boundsKey === 'min') crossAxisBounds[boundsKey] = Math.max(value, oldValue)
              else crossAxisBounds[boundsKey] = Math.min(value, oldValue)
            }
          }

          if (crossAxisBounds.min !== null && crossAxisBounds.max !== null && crossAxisBounds.min > crossAxisBounds.max) {
            crossAxisBounds = null
          }
        }

        // const connectedEndpoint = i === 1 ? sourceEndpoint : i === lastI - 1 ? targetEndpoint : null

        // if (connectedEndpoint) {
        //   const { side } = connectedEndpoint
        //   const boundsKey = (side === 'top' || side === 'left') ? 'max' : 'min'

        //   let spacing = snapNumber(32, vm.diagram.dragAndDropGridSize)
        //   if (boundsKey === 'max') spacing *= -1

        //   crossAxisBounds = {
        //     min: null,
        //     max: null,
        //     [boundsKey]: connectedEndpoint[crossAxis] + spacing,
        //   }
        // }
      }

      return {
        points: [ point1, point2 ],
        axis,
        crossAxis,

        isFirst,
        isLast,

        get x () { return point1.x },
        get y () { return point1.y },
        get width () { return Math.abs(this.length) },
        get rotation () { return (axis === 'x' ? 0 : 90) + (this.length < 0 ? 180 : 0) },

        get axisValue1 () {
          return point1[axis]
        },

        set axisValue1 (value: number) {
          point1[axis] = value
        },

        get axisValue2 () {
          return point2[axis]
        },

        set axisValue2 (value: number) {
          point2[axis] = value
        },

        get crossAxisValue () {
          return point1[crossAxis]
        },

        set crossAxisValue (value: number) {
          if (crossAxisBounds) value = clamp(value, crossAxisBounds.min, crossAxisBounds.max)

          point1[crossAxis] = value
          point2[crossAxis] = value
        },

        set crossAxisValueSnapped (value: number) {
          this.crossAxisValue = snapNumber(value, vm.diagram.dragAndDropGridSize)
        },

        get length () {
          return point2[axis] - point1[axis]
        },

        set length (value: number) {
          point2[axis] = point1[axis] + value
        },
      }
    })

    return lines
  }

  get lineHeight () {
    return Math.max(this.lineThickness, 20)
  }

  get linePadding () {
    return (this.lineHeight - this.lineThickness) / 2
  }

  get pointSizeInner () {
    return this.lineThickness + 12
  }

  get pointSize () {
    return Math.max(this.lineHeight, this.pointSizeInner)
  }

  get pointPadding () {
    return (this.pointSize - this.pointSizeInner) / 2
  }

  onDestroy: (() => void) | null = null

  mounted () {
    const graph = this.graphVm._graph
    if (!graph) return

    graph.on('add remove select unselect', this.updateEdge)

    this.updateEdge()

    // Dragging
    {
      let cleanup: (() => void) | null = null

      this.$watch(() => this.n_dragging, dragging => {
        cleanup?.()

        if (!dragging) return

        let dragTempLineI: number | null = null

        const onMouseMove = (event: MouseEvent) => {
          if (!this._edge) return

          dragging.moved = true

          let mousePos = this.mousePosToModelPos(event.clientX, event.clientY)
          mousePos.x += dragging.offset.x
          mousePos.y += dragging.offset.y

          for (const line of dragging.lines) {
            const { crossAxis } = line
            line.crossAxisValueSnapped = mousePos[crossAxis]
          }

          if (dragTempLineI !== null) {
            const tempLine = this.n_lines[dragTempLineI]
            tempLine.crossAxisValueSnapped = mousePos[tempLine.crossAxis]
          }

          // Functionality for dragging endpoints to other sides
          if (dragging.endpointMode) (() => {
            const [ line ] = dragging.lines

            const endpointName =
              line.isFirst ? 'source' :
              line.isLast ? 'target' :
              null

            if (!endpointName) return

            const endpoint = this[`n_${endpointName}Endpoint` as const]
            if (!endpoint) return

            const rect = cyUtil.node.getRect(this._edge[endpointName]())

            const relativeX =
              mousePos.x < rect.x.left ? 'left' :
              mousePos.x > rect.x.right ? 'right' :
              'inside'

            const relativeY =
              mousePos.y < rect.y.top ? 'top' :
              mousePos.y > rect.y.bottom ? 'bottom' :
              'inside'

            let side: Side | null =
              relativeX === 'inside' && relativeY !== 'inside' ? relativeY :
              relativeY === 'inside' && relativeX !== 'inside' ? relativeX :
              null

            const getSidePos = (side: Side) =>
              side === 'top' ? rect.y.top :
              side === 'bottom' ? rect.y.bottom :
              side === 'left' ? rect.x.left :
              rect.x.right

            if (!side) {
              if (relativeX === 'inside' && relativeY === 'inside') {
                // Cursor is inside the node, pick the closest side.

                let closest: {
                  sideName: Side
                  distance: number
                } | null = null

                for (const sideName of [ 'top', 'bottom', 'left', 'right' ] as const) {
                  const axis = getSideAxis(sideName)
                  const distance = Math.abs(getSidePos(sideName) - mousePos[axis])

                  if (
                    !closest
                    || distance < closest.distance
                    || (distance === closest.distance && sideName === endpoint.side)
                  ) closest = {
                    sideName,
                    distance,
                  }
                }

                if (closest) side = closest?.sideName
              } else if (relativeX !== 'inside' && relativeY !== 'inside') {
                const xDistance = Math.abs(getSidePos(relativeX) - mousePos.x)
                const yDistance = Math.abs(getSidePos(relativeY) - mousePos.y)

                side =
                  xDistance > yDistance ? relativeX :
                  yDistance > xDistance ? relativeY :
                  null
              }
            }

            if (!side || side === endpoint.side) return

            const axis = getSideAxis(side)
            const crossAxis = getCrossAxis(axis)

            const newAxisValue = getSidePos(side)

            const oldEndpointPos = {
              x: endpoint.x,
              y: endpoint.y,
            }

            const newEndpoint: NEndpoint = {
              ...oldEndpointPos,
              [axis]: newAxisValue,
              [crossAxis]: mousePos[crossAxis],
              side,
              axis,
            }

            const { dragAndDropGridSize: gridSize } = this.diagram

            const crossAxisBounds = getRectAxisBounds(crossAxis, rect)

            newEndpoint[crossAxis] = clamp(snapNumber(newEndpoint[crossAxis], gridSize), crossAxisBounds.min, crossAxisBounds.max)

            let newPoints: NPoint[] = [ ...this.n_points ]

            newPoints.splice(endpointName === 'source' ? 0 : -1, 1, newEndpoint)

            // {
            //   newPoints = newPoints.filter(point => !point.temp)

            //   const newTempPoints: NPoint[] = []

            //   if (axis === endpoint.axis) {
            //     // Add 2 temp points.
            //     const p1 = {
            //       x: newEndpoint.x,
            //       y: newEndpoint.y,
            //       [axis]: getSpacedSidePos(side),
            //       temp: true,
            //     }

            //     let closestSide: Side

            //     if (axis === 'x') {
            //       const topDist = Math.abs(getSidePos('top') - newEndpoint.y)
            //       const bottomDist = Math.abs(getSidePos('bottom') - newEndpoint.y)
            //       closestSide = topDist < bottomDist ? 'top' : 'bottom'
            //     } else {
            //       const leftDist = Math.abs(getSidePos('left') - newEndpoint.x)
            //       const rightDist = Math.abs(getSidePos('right') - newEndpoint.x)
            //       closestSide = leftDist < rightDist ? 'left' : 'right'
            //     }

            //     const p2 = {
            //       ...p1,
            //       [crossAxis]: getSpacedSidePos(closestSide),
            //     }

            //     newTempPoints.push(p1, p2)

            //     // Align the axis of the next point with the new temp point to avoid disconnected lines.
            //     const nextPoint = endpointName === 'source'
            //       ? newPoints[1]
            //       : newPoints[newPoints.length - 2]

            //     nextPoint[crossAxis] = p2[crossAxis]
            //   } else {
            //     // Add 1 temp point.
            //     const newTempPoint = {
            //       x: newEndpoint.x,
            //       y: newEndpoint.y,
            //       [axis]: getSpacedSidePos(side),
            //       temp: true,
            //     }

            //     newTempPoints.push(newTempPoint)

            //     // Align the axis of the next point with the new temp point to avoid disconnected lines.
            //     const nextPoint = endpointName === 'source'
            //       ? newPoints[1]
            //       : newPoints[newPoints.length - 2]

            //     nextPoint[axis] = newTempPoint[axis]
            //   }

            //   if (endpointName === 'target') newTempPoints.reverse()

            //   newPoints.splice(endpointName === 'source' ? 1 : -1, 0, ...newTempPoints)
            // }

            // When switching axis we need either one less or one more point.
            if (axis !== endpoint.axis) {
              const tempPointI = endpointName === 'source' ? 1 : newPoints.length - 2

              let oldTempPoint: NPoint | null = newPoints.length > 3 ? newPoints[tempPointI] : null
              if (!oldTempPoint?.temp) oldTempPoint = null

              // If there's an old temp point...
              if (oldTempPoint) {
                // Delete it.
                newPoints.splice(tempPointI, 1)

                // Align the crossAxis of the next point with the new endpoint to avoid disconnected lines.
                const nextPoint = endpointName === 'source'
                  ? newPoints[tempPointI]
                  : newPoints[tempPointI - 1]

                nextPoint[crossAxis] = newEndpoint[crossAxis]

                dragTempLineI = null
              } else {
                let insertI = tempPointI
                if (endpointName === 'target') insertI++

                const axisValue = snapNumber(mousePos[axis], gridSize)

                // Otherwise, create one.
                newPoints.splice(insertI, 0, {
                  x: newEndpoint.x,
                  y: newEndpoint.y,
                  [axis]: axisValue,
                  temp: true,
                })

                const nextPoint = endpointName === 'source'
                  ? newPoints[tempPointI + 1]
                  : newPoints[tempPointI]

                nextPoint[axis] = axisValue

                dragTempLineI = insertI
              }
            }

            this[`n_${endpointName}Endpoint` as const] = newEndpoint

            this.n_points = newPoints

            dragging.lines = [ this.n_lines[endpointName === 'source' ? 0 : this.n_lines.length - 1] ]

            {
              const connectedLine = this.n_lines[endpointName === 'source' ? 1 : this.n_lines.length - 2]
              connectedLine.crossAxisValueSnapped = connectedLine.crossAxisValue
            }
          })()

          this.updateCustomTaxi(false)
        }

        const onMouseUp = (event?: MouseEvent) => {
          // event?.preventDefault()
          // event?.stopPropagation()

          cleanup?.()

          if (this.n_dragging) {
            const { moved } = this.n_dragging
            this.n_dragging = null
            if (moved) this.updateCustomTaxi(true)
          }
        }

        window.addEventListener('mousemove', onMouseMove)
        window.addEventListener('mouseup', onMouseUp)

        cleanup = () => {
          window.removeEventListener('mousemove', onMouseMove)
          window.removeEventListener('mouseup', onMouseUp)
          cleanup = null
        }
      })
    }
  }

  beforeDestroy () {
    const graph = this.graphVm._graph
    if (!graph) return

    graph.off('add remove select unselect', 'edge', this.updateEdge)

    this.setEdge(null)
  }

  setEdge (edge: EdgeSingular | null) {
    const oldEdge = this._edge
    if (edge === oldEdge) return

    this._edge = edge

    this.n_dragging = null

    if (oldEdge) {
      oldEdge.off('data style', this.onEdgeData)
    }

    if (edge) {
      this.onEdgeData()
      edge.on('data style', this.onEdgeData)
    }

    this.updatePoints()
  }

  updateEdge () {
    const { graph } = this

    const selectedElements = graph.elements(':selected')

    let edge: EdgeSingular | null = null

    if (selectedElements.length === 1) {
      const element = selectedElements[0]
      if (element.isEdge() && element.is(':simple')) {
        edge = element
      }
    }

    this.setEdge(edge)
  }

  onEdgeData () {
    const { _edge: edge } = this
    if (!edge) return

    const relation: Relation = edge.data('relation')

    this.lineThickness = relation.builtStyle.lineWidth ?? 0

    if (!this.n_dragging) requestAnimationFrame(() => {
      if (!this.n_dragging) this.updatePoints()
    })
  }

  updatePoints () {
    const { _edge: edge } = this

    const relation: Relation | undefined = edge?.data('relation')

    if (!edge || !relation?.builtStyle.taxi) {
      this.n_sourceEndpoint = null
      this.n_targetEndpoint = null
      this.n_points = []
      return
    }

    const customTaxi: CustomTaxi | null = edge.data('customTaxi') ?? null

    const getEndpoint = (type: 'source' | 'target'): NEndpoint => {
      const nodeRect = cyUtil.node.getRect(edge[type]())

      let side: Side
      let position: Position

      if (customTaxi) {
        const customTaxiEndpoint = customTaxi[type === 'source' ? 'from' : 'to']
        side = customTaxiEndpoint.side
        position = {
          x: new Decimal(nodeRect.x.center).plus(new Decimal(nodeRect.width).times(customTaxiEndpoint.x)).toNumber(),
          y: new Decimal(nodeRect.y.center).plus(new Decimal(nodeRect.height).times(customTaxiEndpoint.y)).toNumber(),
        }
      } else {
        position = edge[`${type}Endpoint` as const]()
        side = getRectPositionSide(nodeRect, position)
      }

      return {
        side,
        axis: getSideAxis(side),
        x: position.x,
        y: position.y,
      }
    }

    const sourceEndpoint = getEndpoint('source')
    const targetEndpoint = getEndpoint('target')

    const minLines = sourceEndpoint.axis === targetEndpoint.axis ? 3 : 2
    const minPoints = minLines + 1

    const points: NPoint[] = []

    let segmentPoints: CustomTaxiSegmentPoint[]

    if (customTaxi) {
      segmentPoints = customTaxi.segmentPoints
    } else {
      const edgeSegmentPoints = edge.segmentPoints() as Position[] | undefined
      if (!edgeSegmentPoints) return
      segmentPoints = edgeSegmentPoints.map(point => ({ ...point, temp: true }))
    }

    if (segmentPoints.length >= minPoints - 2) {
      let prevPoint: NPoint = sourceEndpoint
      let prevAxis = getCrossAxis(sourceEndpoint.axis)

      for (let point of segmentPoints) {
        const axis = getCrossAxis(prevAxis)

        point = {
          ...point,
          [prevAxis]: prevPoint[prevAxis],
        }

        points.push(point)

        prevPoint = point
        prevAxis = axis
      }

      let lastPoint = prevPoint
      let lastAxis = prevAxis

      const targetAxis = targetEndpoint.axis
      const targetCrossAxis = getCrossAxis(targetAxis)

      // If the last points axis is the same as the target endpoint,
      // we need to create a new point.
      if (lastAxis === targetAxis) {
        lastPoint = { ...lastPoint }
        lastAxis = getCrossAxis(lastAxis)
        points.push(lastPoint)
      }

      // Make sure the last point is aligned with the target endpoint on the crossAxis.
      lastPoint[targetCrossAxis] = targetEndpoint[targetCrossAxis]
    }

    this.n_sourceEndpoint = sourceEndpoint
    this.n_targetEndpoint = targetEndpoint
    this.n_points = [ sourceEndpoint, ...points, targetEndpoint ]
  }

  mousePosToModelPos (clientX: number, clientY: number) {
    const graph = this.graphVm._graph
    if (!graph) return { x: clientX, y: clientY }

    const graphRect = this.graphVm.el.getBoundingClientRect()

    return cyUtil.pos.renderedToModel(graph, {
      x: clientX - graphRect.left,
      y: clientY - graphRect.top,
    })
  }

  onLineDblClick (i: number, event: MouseEvent) {
    const line = this.n_lines[i]
    const axisValueMin = Math.min(line.axisValue1, line.axisValue2)
    const axisValueMax = Math.max(line.axisValue1, line.axisValue2)

    const pos = this.mousePosToModelPos(event.clientX, event.clientY)
    pos[line.axis] = clamp(snapNumber(pos[line.axis], this.diagram.dragAndDropGridSize), axisValueMin, axisValueMax)
    pos[line.crossAxis] = line.crossAxisValue

    this.n_points.splice(i + 1, 0, { ...pos }, { ...pos })

    this.updateCustomTaxi(true)
  }

  onPointDblClick (i: number, event: MouseEvent) {
    if (this.n_points.length <= 4 || !i || i === this.n_points.length - 1) return

    if (i > 1) i--

    const line = this.n_lines[i]

    const lineBefore = this.n_lines[i - 1]
    const lineAfter = this.n_lines[i + 1]

    if (!lineAfter.isLast) {
      line.crossAxisValue = lineAfter.axisValue2
      lineAfter.crossAxisValue = lineBefore.crossAxisValue

      if (lineAfter.crossAxisValue !== lineBefore.crossAxisValue) {
        lineBefore.crossAxisValue = lineAfter.crossAxisValue
      }
    } else {
      line.crossAxisValue = lineBefore.axisValue1
      lineBefore.crossAxisValue = lineAfter.crossAxisValue

      if (lineBefore.crossAxisValue !== lineAfter.crossAxisValue) {
        lineAfter.crossAxisValue = lineBefore.crossAxisValue
      }
    }

    this.n_points.splice(i, 2)

    for (const line of this.n_lines.slice(1, -1)) {
      const value = line.crossAxisValue
      line.crossAxisValue = value
    }

    this.updateCustomTaxi(true)
  }

  updateCustomTaxi (commit = false) {
    const {
      _edge: edge,
      n_sourceEndpoint: sourceEndpoint,
      n_targetEndpoint: targetEndpoint,
    } = this

    if (!edge || !sourceEndpoint || !targetEndpoint) return

    const newCustomTaxi = {
      from: createCustomTaxiEndpoint(sourceEndpoint, cyUtil.node.getRect(edge.source())),
      to: createCustomTaxiEndpoint(targetEndpoint, cyUtil.node.getRect(edge.target())),
      segmentPoints: this.n_points.slice(1, -1).map(point => ({ x: point.x, y: point.y, temp: point.temp })),
    }

    if (commit) {
      this.diagram.activeDiagram.data.commitChange({
        edit: {
          relations: [
            {
              id: edge.data('relation').id,
              customTaxi: newCustomTaxi,
            },
          ],
        },
      })
    } else {
      const oldCustomTaxi = edge.data('customTaxi')
      edge.data('customTaxi', newCustomTaxi)
      if (!oldCustomTaxi) this.diagram.eventBus.emit({ name: 'graph.spreadTaxiEdges' })
    }
  }
}
</script>

