<template>
  <div
    :class="[
      'lassox-diagram__FieldContainer',
      disabled && 'lassox-diagram__FieldContainer--disabled',
      error && 'lassox-diagram__FieldContainer--error',
    ]"
  >
    <div
      v-if="label"
      class="lassox-diagram__FieldContainer_label"
      v-text="label"
    />

    <slot></slot>

    <div
      v-if="helperText || $slots['helper-text']"
      class="lassox-diagram__FieldContainer_helper-text"
    >
      <slot name="helper-text">{{ helperText }}</slot>
    </div>
  </div>
</template>

<script lang="ts">
import { Vue, Component, Prop } from 'vue-property-decorator'

@Component({})

export default class FieldContainer extends Vue {
  @Prop({ type: Boolean, default: false })
  readonly disabled!: boolean

  @Prop(String)
  readonly label?: string

  @Prop(String)
  readonly helperText?: string

  @Prop(Boolean)
  readonly error?: boolean
}
</script>

<style lang="scss">
.lassox-diagram__FieldContainer {
  display: flex;
  flex-direction: column;

  &_label,
  &_helper-text {
    opacity: 1;
    transition: opacity 100ms;
  }

  &_label {
    padding-bottom: 8px;
    margin: -2px 0;
    font-size: 12px;
    line-height: 16px;
  }

  &_helper-text {
    padding-top: 8px;
    margin: -2px 0;
    font-size: 12px;
    line-height: 16px;
  }

  &--disabled &_label,
  &--disabled &_helper-text {
    opacity: 0.5;
  }

  &--error &_label,
  &--error &_helper-text {
    color: #EF4444;
  }
}
</style>
